  let denied = 0;
  for (const [actor, length] of [
    [none, 1],
    [plan, undefined],
    [plan, 0],
    [plan, 67108865],
  ] as const) {
    try {
      contract.documentBrowserActorLeaseFromPlanV1(actor, source, actor.kind === "none" ? "react" : "wasm", length);
    } catch {
      denied++;
    }
  }
  let accessorReads = 0;
  for (const candidate of [
    undefined,
    null,
    [],
