  "plugin-closed-shape": 41, // flat 41/41/41 across 3 runs ~90-100s apart, 2026-08-13 ~00:12-00:16 — 📓️w5-ratchet-report.md
  "plugin-dependency-allowlist": 105, // flat 105/105/105 across 3 runs ~90-100s apart, 2026-08-13 ~00:12-00:16 — 📓️w5-ratchet-report.md
  "plugin-dependency-os-host": 10, // flat 10/10/10 across 3 runs ~90-100s apart, 2026-08-13 ~00:12-00:16 — 📓️w5-ratchet-report.md
  "effect-capability-parity": 47, // flat 47/47/47 across 3 runs ~90-100s apart, 2026-08-13 ~00:12-00:16 — 📓️w5-ratchet-report.md
};

/** 🔑Ratchet grouping key for a breach `kind` — every `taxonomy/plugin-purity-*` sub-kind (filesystem-io, interior-mutability-*, thread-local-state, ts-side-effect, …) collapses onto one shared `"plugin-purity"` key matching the ceiling table's single combined row; every other APA kind keeps a 1:1 key. */
function policyApaRatchetKey(kind: string): string {
  if (kind.startsWith("taxonomy/plugin-purity-")) return "plugin-purity";
  return kind.startsWith("taxonomy/") ? kind.slice("taxonomy/".length) : kind;
}

/**
 * 🚦Applies the shrink-only ratchet: groups `breaches` by `policyApaRatchetKey`, and for any key present in
 * `POLICY_APA_RATCHET_CEILINGS`, keeps the first `ceiling` breaches at their original `medium` priority and
 * promotes only the breaches beyond the ceiling to `high` with a regression message naming the key, the
 * ceiling, and the measured count. Keys absent from the table pass through untouched, always `medium`.
 */
function policyApaRatchetApply(breaches: readonly BreachRecord[]): BreachRecord[] {
  const grouped = new Map<string, BreachRecord[]>();
  for (const b of breaches) {
    const key = policyApaRatchetKey(b.kind);
    const list = grouped.get(key);
    if (list) list.push(b);
    else grouped.set(key, [b]);
  }
  const out: BreachRecord[] = [];
  for (const [key, list] of grouped) {
    const ceiling = POLICY_APA_RATCHET_CEILINGS[key];
    if (ceiling === undefined || list.length <= ceiling) {
      out.push(...list);
      continue;
    }
    list.forEach((b, i) => {
      if (i < ceiling) {
        out.push(b);
        return;
      }
      out.push({
        ...b,
        priority: "high",
        summary: `RATCHET REGRESSION on "${key}": ceiling is ${ceiling}, measured ${list.length} — shrink-only, raising the ceiling requires a ticket citation — ${b.summary}`,
      });
    });
  }
  return out;
}

/**
 * 🎯Combined, ratcheted breach set for all five APA rules — the single call site both `policy`'s
 * aggregator and `VerifyScript.runGate`'s `dissolveBreaches` block use, so census and gate can never
 * disagree on a breach's priority.
 */
function policyApaBreaches(repoRoot: string): BreachRecord[] {
  return policyApaRatchetApply([
    ...policyPluginClosedShapeBreaches(repoRoot),
    ...policyPluginPurityBreaches(repoRoot),
    ...policyStateLaneExhaustivenessBreaches(repoRoot),
    ...policyDeclarativeRegistrationBreaches(repoRoot),
    ...policyPluginDependencyAllowlistBreaches(repoRoot),
    ...policyEffectCapabilityParityBreaches(repoRoot),
  ]);
}
//#endregion 🔧️PolicyRuleApaRatchet

//#endregion 🔧️PolicyRuleArtifactsOnlyPluginArchitecture


//#region 🔧️PolicyRuleSubsetConformance
/** 🪆️ Subset ownership + roundtrip readiness policies (ticket 26/08/12/SUBSET-CONFORMANCE-AND-INTEGRATED-ROUNDTRIPS). Medium until seal. */

function policyListTopLevelSubsetDirs(repoRoot: string): string[] {
  const taxonomy = loadTaxonomy();
  const out: string[] = [];
  const pluginsRoot = join(repoRoot, "✏️s/🔌️plugins");
  if (!existsSync(pluginsRoot)) return out;
  for (const plugin of readdirSync(pluginsRoot, { withFileTypes: true })) {
    if (!plugin.isDirectory()) continue;
    const arts = join(pluginsRoot, plugin.name, taxonomy.artifactsDirName ?? "🗿️artifacts");
    if (!existsSync(arts)) continue;
    for (const art of readdirSync(arts, { withFileTypes: true })) {
      if (!art.isDirectory()) continue;
      const standards = join(arts, art.name, taxonomy.standardsDirName ?? "🏅️standards");
      if (!existsSync(standards)) continue;
      for (const std of readdirSync(standards, { withFileTypes: true })) {
        if (!std.isDirectory() || !std.name.startsWith(taxonomy.standardDirPrefix ?? "🔖️")) continue;
        const subsets = join(standards, std.name, taxonomy.subsetsDirName ?? "🪆️subsets");
        if (!existsSync(subsets)) continue;
        const subsetsRel = relative(repoRoot, subsets).replaceAll("\\", "/");
        for (const sub of readdirSync(subsets, { withFileTypes: true })) {
          if (!sub.isDirectory() || subsetIdForDirectoryName(subsetsRel, sub.name, taxonomy) === null) continue;
          out.push(join("✏️s/🔌️plugins", plugin.name, taxonomy.artifactsDirName ?? "🗿️artifacts", art.name, taxonomy.standardsDirName ?? "🏅️standards", std.name, taxonomy.subsetsDirName ?? "🪆️subsets", sub.name).replaceAll("\\", "/"));
        }
      }
    }
  }
  return out;
}

/** 🪆️ Every subset must own schema, engine, io, and (eventually) examples. */
export function policySubsetFacetTotalityBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const required = taxonomy.subsetChildDirs ?? ["🧬️schema", "⚙️engine", "🚪️io", "📚️examples"];
  const breaches: BreachRecord[] = [];
  for (const subRel of policyListTopLevelSubsetDirs(repoRoot)) {
    for (const child of required) {
      // examples are required structurally but many are still relocating — keep medium
      if (!existsSync(join(repoRoot, subRel, child))) {
        breaches.push({
          id: `subset-facet-missing-${subRel}/${child}`,
          summary: `"${subRel}" is missing required child ${child}/`,
          kind: "subset-conformance/facet-totality",
          scope: subRel,
          priority: "medium",
          reason: "Subsets own schema, engine, IO, and examples.",
          solution: `Create ${subRel}/${child}/ as part of the subset ownership migration.`,
        });
      }
    }
  }
  return breaches;
}

/**
 * ⚙️ An artifact is a `🧬️schema` (snapshot, diff, mutations, inferences) plus a `🚪️io` system — never
 * an engine. Behaviour belongs to the app that edits the artifact (`🎛️apps/<app>/⚙️engine`, already a
 * required app component); pure algorithms belong one level up, in a module's `⚙️engine`, which
 * `taxonomyLeafParentDirs` keeps globally legal.
 *
 * Replaces the two rules that previously *mandated* the facet — `policySubsetEnginePresenceBreaches`
 * and `policyArtifactEnginePresenceBreaches` — the latter of which gated at `high` on a missing
 * folder. Both served `ArtifactEngine`, a trait that never shipped (`grep -rn "trait ArtifactEngine"`
 * → 0 hits; see `🏪️store/🦀️.rs`'s own note that it "never existed as a live trait").
 *
 * Lands at `low` while the 95 existing dirs burn down, then rises to `high` once the count is zero —
 * verified by counting directories on disk, never via the breach cache. Ticket
 * 26/08/12/ENGINELESS-ARTIFACTS-AND-APP-STATE-MACHINES (#2553).
 */
export function policyArtifactEngineFacetForbiddenBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const artRel of policyListPluginArtifactDirs(repoRoot)) {
    for (const owner of policyArtifactEngineOwnerDirs(repoRoot, artRel)) {
      if (!existsSync(join(repoRoot, join(owner, POLICY_ENGINE_FACET)))) continue;
      breaches.push({
        id: `artifact-engine-forbidden-${owner}`,
        summary: `"${owner}" declares a forbidden ${POLICY_ENGINE_FACET}/ facet`,
        kind: "subset-conformance/engine-forbidden",
        scope: owner,
        priority: "low",
        reason: "An artifact has a schema (snapshot, diff, mutations, inferences), an io system and examples — never an engine.",
        solution: `Dissolve ${owner}/${POLICY_ENGINE_FACET} per the D0–D6 procedure: derived compute → 🧬️schema/💡️inferences, (de)serialization → 🚪️io, edits → a 🧬️mutations triad, behaviour → the app's ⚙️engine, pure algorithms → a module's ⚙️engine one level up. Then delete the directory.`,
      });
    }
  }
  return breaches;
}

/** ⚙️ Every level of an artifact tree that could carry an `⚙️engine`: the artifact, its standards, and their subsets. */
function policyArtifactEngineOwnerDirs(repoRoot: string, artRel: string): string[] {
  const owners = [artRel];
  const standardsRel = join(artRel, "🏅️standards");
  for (const std of policyReaddirSafe(repoRoot, standardsRel).filter((e) => e.isDirectory)) {
    const stdRel = join(standardsRel, std.name);
    owners.push(stdRel);
    const subsetsRel = join(stdRel, "🪆️subsets");
    for (const subset of policyReaddirSafe(repoRoot, subsetsRel).filter((e) => e.isDirectory)) {
      owners.push(join(subsetsRel, subset.name));
    }
  }
  return owners;
}

/** 📚️ Examples must not remain at artifact/standard level. */
export function policyExampleNotAtArtifactLevelBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const pluginsRoot = join(repoRoot, "✏️s/🔌️plugins");
  if (!existsSync(pluginsRoot)) return breaches;
  for (const plugin of readdirSync(pluginsRoot, { withFileTypes: true })) {
    if (!plugin.isDirectory()) continue;
    const arts = join(pluginsRoot, plugin.name, "🗿️artifacts");
    if (!existsSync(arts)) continue;
    for (const art of readdirSync(arts, { withFileTypes: true })) {
      if (!art.isDirectory()) continue;
      const artEx = join(arts, art.name, "📚️examples");
      if (existsSync(artEx)) {
        const rel = join("✏️s/🔌️plugins", plugin.name, "🗿️artifacts", art.name, "📚️examples").replaceAll("\\", "/");
        breaches.push({
          id: `artifact-examples-remaining-${rel}`,
          summary: `artifact-level examples still present at "${rel}"`,
          kind: "subset-conformance/example-placement",
          scope: rel,
          priority: "medium",
          reason: "Examples belong under 🪆️subsets/<id>/📚️examples/.",
          solution: "Move example units into the owning subset then delete the artifact examples dir.",
        });
      }
      const standards = join(arts, art.name, "🏅️standards");
      if (!existsSync(standards)) continue;
      for (const std of readdirSync(standards, { withFileTypes: true })) {
        if (!std.isDirectory()) continue;
        const stdEx = join(standards, std.name, "📚️examples");
        if (existsSync(stdEx)) {
          const rel = join("✏️s/🔌️plugins", plugin.name, "🗿️artifacts", art.name, "🏅️standards", std.name, "📚️examples").replaceAll("\\", "/");
          breaches.push({
            id: `standard-examples-remaining-${rel}`,
            summary: `standard-level examples still present at "${rel}"`,
            kind: "subset-conformance/example-placement",
            scope: rel,
            priority: "medium",
            reason: "Examples belong under 🪆️subsets/<id>/📚️examples/.",
            solution: "Move into the owning subset then delete the standard examples dir.",
          });
        }
      }
    }
  }
  return breaches;
}

/** 🧹 Phantom Chinese 🏅️标准 trees must be deleted. */
export function policyPhantomStandardsBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const pluginsRoot = join(repoRoot, "✏️s/🔌️plugins");
  if (!existsSync(pluginsRoot)) return breaches;
  const walk = (dir: string, rel: string) => {
    if (!existsSync(dir)) return;
    for (const ent of readdirSync(dir, { withFileTypes: true })) {
      if (!ent.isDirectory()) continue;
      const childRel = `${rel}/${ent.name}`.replaceAll("\\", "/");
      if (ent.name.includes("标准")) {
        breaches.push({
          id: `phantom-standards-${childRel}`,
          summary: `corrupt standards tree "${childRel}"`,
          kind: "subset-conformance/phantom-standards",
          scope: childRel,
          priority: "medium",
          reason: "Chinese-named 🏅️标准 directories are corrupt phantoms.",
          solution: "Delete the entire phantom tree.",
        });
      }
      walk(join(dir, ent.name), childRel);
    }
  };
  walk(pluginsRoot, "✏️s/🔌️plugins");
  return breaches;
}

/** 🪞 Meta-only TypeScript subset schema leaves (≤7 lines) must become real mirrors. */
export function policySubsetTsParityBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const subRel of policyListTopLevelSubsetDirs(repoRoot)) {
    const ts = join(repoRoot, subRel, "🧬️schema", (POLICY_TS_COMPONENT_LEAF));
    if (!existsSync(ts)) continue;
    const lines = readFileSync(ts, "utf8").split(/\r?\n/).length;
    if (lines > 0 && lines <= 7) {
      breaches.push({
        id: `subset-ts-meta-stub-${subRel}`,
        summary: `"${subRel}/🧬️schema/${POLICY_TS_COMPONENT_LEAF}" is a ${lines}-line meta stub`,
        kind: "subset-conformance/ts-parity",
        scope: `${subRel}/🧬️schema/${POLICY_TS_COMPONENT_LEAF}`,
        priority: "medium",
        reason: "Derived/owning subsets require a real TypeScript implementation mirroring Rust.",
        solution: "Replace the meta stub with a full TypeScript mirror of the Rust conformance/schema surface.",
      });
    }
  }
  return breaches;
}

/** 🚫 Glue compatibility shims keeping pre-migration module paths must be deleted. */
export function policyNoGlueShimBlocksBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const pluginsRoot = join(repoRoot, "✏️s/🔌️plugins");
  if (!existsSync(pluginsRoot)) return breaches;
  for (const plugin of readdirSync(pluginsRoot, { withFileTypes: true })) {
    if (!plugin.isDirectory()) continue;
    const glue = join(pluginsRoot, plugin.name, "📦️packages/🦀️rust/🦀️.rs");
    if (!existsSync(glue)) continue;
    const content = readFileSync(glue, "utf8");
    if (/Shims:\s*keep pre-migration|pre-migration module paths/i.test(content)) {
      const rel = join("✏️s/🔌️plugins", plugin.name, "📦️packages/🦀️rust/🦀️.rs").replaceAll("\\", "/");
      breaches.push({
        id: `glue-shim-${rel}`,
        summary: `"${rel}" still contains pre-migration shim blocks`,
        kind: "subset-conformance/no-glue-shim-blocks",
        scope: rel,
        priority: "medium",
        reason: "Greenfield forbids compatibility shims.",
        solution: "Delete shim blocks after generated subset registration lands.",
      });
    }
  }
  return breaches;
}

/** 📦 Aggregate subset-conformance scanners. */
export function policySubsetConformanceBreaches(repoRoot: string): BreachRecord[] {
  return [
    ...policySubsetFacetTotalityBreaches(repoRoot),
    ...policyArtifactEngineFacetForbiddenBreaches(repoRoot),
    ...policyExampleNotAtArtifactLevelBreaches(repoRoot),
    ...policyPhantomStandardsBreaches(repoRoot),
    ...policySubsetTsParityBreaches(repoRoot),
    ...policyNoGlueShimBlocksBreaches(repoRoot),
  ];
}
//#endregion 🔧️PolicyRuleSubsetConformance


//#region 🔧️PolicyRuleArtifactViewersEditors
/**
 * 👁️✏️ Ticket 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET, contract §6 "Policies" (W0/W1,
 * add-only). Four rules over the new `👁️viewer`/`✏️editor` subset-surface axis, driven entirely by
 * `🔣️taxonomy.json` (`viewerDirName`/`editorDirName`/`surfaceRoles`/`surfaceDirNames`/
 * `windowLeafLangs` and ecosystem component file-kind IDs) — never a hardcoded emoji literal for the axis itself.
 * `policySubsetSurfaceCompletenessBreaches` and `policyViewerPurityBreaches` land at `"medium"`/`"high"`
 * respectively per the contract; `policyOsConfigShapeBreaches` locks a facet that already shipped
 * (C4), so it fails the gate like any other completed-shape lock.
 */

/** 👁️✏️ Every OWNED subset (has `🧬️schema`, independent of `🚪️io` — see the scaffolder's identical
 * predicate in `📇️registry/📜️script.ts`) carries both `👁️viewer`/`✏️editor`, each with ≥1 mode
 * carrying ≥1 window with both `windowLeafLangs` leaves. A surface whose scaffolded leaves still carry
 * the `SCAFFOLD` marker is a separate, non-passing breach kind — see the scaffolder region docstring
 * in `📇️registry/📜️script.ts` for why the marker exists. */
export function policySubsetSurfaceCompletenessBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const breaches: BreachRecord[] = [];
  const scaffoldLeafNames = new Set([
    taxonomyMappedFilename(taxonomy, taxonomy.componentFileKinds, "🦀️rust"),
    taxonomyMappedFilename(taxonomy, taxonomy.componentFileKinds, "🟦️typescript"),
  ]);
  for (const subRel of policyListTopLevelSubsetDirs(repoRoot)) {
    if (!existsSync(join(repoRoot, subRel, "🧬️schema"))) continue;
    for (const role of taxonomy.surfaceRoles) {
      const surfaceDirName = taxonomy.surfaceDirNames[role];
      const surfaceRel = `${subRel}/${surfaceDirName}`;
      if (!existsSync(join(repoRoot, surfaceRel))) {
        breaches.push({
          id: `subset-surface-missing-${surfaceRel}`,
          summary: `"${subRel}" is missing required surface "${surfaceDirName}"`,
          kind: "taxonomy/surface-completeness",
          scope: subRel,
          priority: "medium",
          reason: `Every owned subset carries both ${taxonomy.subsetRequiredSurfaceDirs.join(", ")}.`,
          solution: `cd 📇️registry && bun ./📜️script.ts new surface <plugin> <kind> <standard> <subset> ${role} (or "new surface --all" to batch every missing surface).`,
        });
        continue;
      }
      const modesRel = `${surfaceRel}/${taxonomy.modesDirName}`;
      let hasCompleteWindow = false;
      for (const mode of policyReaddirSafe(repoRoot, modesRel).filter((e) => e.isDirectory)) {
        const windowsRel = `${modesRel}/${mode.name}/${taxonomy.windowsDirName}`;
        for (const w of policyReaddirSafe(repoRoot, windowsRel).filter((e) => e.isDirectory)) {
          const windowDir = `${windowsRel}/${w.name}`;
          if (taxonomy.windowLeafLangs.every((lang) => existsSync(join(repoRoot, windowDir, taxonomyMappedFilename(taxonomy, taxonomy.componentFileKinds, lang))))) hasCompleteWindow = true;
        }
      }
      if (!hasCompleteWindow) {
        breaches.push({
          id: `subset-surface-window-incomplete-${surfaceRel}`,
          summary: `"${surfaceRel}" has no mode with a window carrying both ${taxonomy.windowLeafLangs.join(", ")} leaves`,
          kind: "taxonomy/surface-completeness",
          scope: subRel,
          priority: "medium",
          reason: "Every surface must carry at least one mode with at least one window declaring every windowLeafLangs leaf.",
          solution: `Scaffold with "new surface … ${role}" (📇️registry/), then author a real mode/window.`,
        });
      }
      const scaffoldLeaves = policyWalkRelFiles(repoRoot, [surfaceRel], (_p, name) => scaffoldLeafNames.has(name)).filter((relPath) => policyReadFileSafe(repoRoot, relPath).includes("SCAFFOLD"));
      if (scaffoldLeaves.length > 0) {
        breaches.push({
          id: `subset-surface-scaffold-residue-${surfaceRel}`,
          summary: `"${surfaceRel}" still carries ${scaffoldLeaves.length} SCAFFOLD-marker leaf(ves)`,
          kind: "taxonomy/surface-scaffold-residue",
          scope: subRel,
          priority: "medium",
          reason: "A surface at scaffold content is not a finished W2 packet — the SCAFFOLD marker exists so this can never masquerade as done.",
          solution: `Author real render/view-model/commands for ${scaffoldLeaves.slice(0, 3).join(", ")}${scaffoldLeaves.length > 3 ? ", …" : ""}, removing the SCAFFOLD marker.`,
        });
      }
    }
  }
  return breaches;
}

/** 👁️ No file under a `👁️viewer` dir may reference mutation dispatch, `artifact_mutations`, or an
 * `::editor::` module path — `ViewEmit` is structurally read-only (contract §2.2); this is the
 * filesystem-content half of that guarantee. */
export function policyViewerPurityBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const breaches: BreachRecord[] = [];
  const patterns: readonly { re: RegExp; label: string }[] = [
    { re: /\.mutation\(/, label: ".mutation(" },
    { re: /Emit::mutations/, label: "Emit::mutations" },
    { re: /artifact_mutations/, label: "artifact_mutations" },
    { re: /::editor::/, label: "::editor::" },
  ];
  for (const subRel of policyListTopLevelSubsetDirs(repoRoot)) {
    const viewerRel = `${subRel}/${taxonomy.viewerDirName}`;
    if (!existsSync(join(repoRoot, viewerRel))) continue;
    for (const relPath of policyWalkRelFiles(repoRoot, [viewerRel], () => true)) {
      const content = policyReadFileSafe(repoRoot, relPath);
      for (const { re, label } of patterns) {
        if (!re.test(content)) continue;
        breaches.push({
          id: `viewer-purity-${relPath}-${label}`,
          summary: `"${relPath}" under a ${taxonomy.viewerDirName} dir matches forbidden pattern "${label}"`,
          kind: "taxonomy/viewer-purity",
          scope: subRel,
          priority: "high",
          reason: "ViewEmit is structurally read-only; no file under a viewer surface may reference mutation dispatch, artifact_mutations, or an editor-only module path.",
          solution: `Remove the "${label}" reference from ${relPath}, or move the mutating logic to the sibling ${taxonomy.editorDirName} surface.`,
        });
      }
    }
  }
  return breaches;
}

/** 🔗️A surface dir under a subset this plugin does NOT own (no `🧬️schema` of its own — a contributed,
 * mirrored surface per `contributedSubsetChildDirs`) must be backed by a `.depends_on(<owner-plugin>)`
 * on the contributing plugin's builder, exactly like `policyContributionTargetBreaches` requires for
 * mutation/inference contributions. Dormant on today's tree (no contributed surface exists yet — every
 * scaffolded surface sits under a subset its own plugin owns), verified structurally sound so it fires
 * correctly once W2 packets start contributing surfaces onto foreign kinds. */
export function policyContributedSurfaceTargetBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const breaches: BreachRecord[] = [];
  const subsetRels = policyListTopLevelSubsetDirs(repoRoot);
  const pluginRootOf = (subRel: string): string => subRel.split("/").slice(0, 3).join("/");
  const ownerRootBySuffix = new Map<string, string>();
  for (const subRel of subsetRels) {
    if (!existsSync(join(repoRoot, subRel, "🧬️schema"))) continue;
    const pluginRoot = pluginRootOf(subRel);
    const suffix = subRel.slice(pluginRoot.length + 1);
    if (!ownerRootBySuffix.has(suffix)) ownerRootBySuffix.set(suffix, pluginRoot);
  }
  for (const subRel of subsetRels) {
    if (existsSync(join(repoRoot, subRel, "🧬️schema"))) continue; // this plugin owns this triple — not a contribution
    const pluginRoot = pluginRootOf(subRel);
    const suffix = subRel.slice(pluginRoot.length + 1);
    const ownerRoot = ownerRootBySuffix.get(suffix);
    for (const role of taxonomy.surfaceRoles) {
      const surfaceRel = `${subRel}/${taxonomy.surfaceDirNames[role]}`;
      if (!existsSync(join(repoRoot, surfaceRel))) continue;
      if (!ownerRoot) {
        breaches.push({
          id: `contributed-surface-unknown-owner-${surfaceRel}`,
          summary: `"${surfaceRel}" contributes a surface but no other plugin owns "${suffix}"`,
          kind: "plugin-dependency/contributed-surface-target",
          scope: pluginRoot,
          priority: "medium",
          reason: "A contributed surface must mirror the path of a subset some OTHER plugin actually owns (has 🧬️schema for).",
          solution: `Verify "${suffix}" is a real owned subset elsewhere, or remove ${surfaceRel} if it is stray.`,
        });
        continue;
      }
      if (ownerRoot === pluginRoot) continue;
      const ownerPluginId = policyStripEmoji(ownerRoot.split("/").pop() ?? "");
      const declared = policyOwnerOwnComponentFiles(repoRoot, pluginRoot).some((relPath) =>
        new RegExp(`\\.depends_on\\s*\\(\\s*"${ownerPluginId}"`).test(policyReadFileSafe(repoRoot, relPath)),
      );
      if (declared) continue;
      breaches.push({
        id: `contributed-surface-target-undeclared-${surfaceRel}`,
        summary: `"${surfaceRel}" contributes a surface onto "${ownerPluginId}"'s subset without declaring .depends_on("${ownerPluginId}")`,
        kind: "plugin-dependency/contributed-surface-target",
        scope: pluginRoot,
        priority: "high",
        reason: "A surface contributed onto a subset this plugin does not own must be backed by a declared dependency on the owning plugin (surface.contribution-not-permitted).",
        solution: `Add .depends_on("${ownerPluginId}", …) to the plugin/extension builder in ${pluginRoot}.`,
      });
    }
  }
  return breaches;
}

const POLICY_OS_CONFIG_ROOT = "🧰️framework/🛍️products/💻️os/🎚️config";
const POLICY_OS_CONFIG_SCHEMA_ID = "os.config.opening";
const POLICY_OS_CONFIG_MUTATION_KINDS = ["set-default-app", "clear-default-app"] as const;

/** 🎚️Locks the shape of the already-shipped C4 OS config facet: five `schemaFormats` leaves, the
 * frozen `os.config.opening` schema id, and both direct `set-default-app`/`clear-default-app`
 * mutations. Content-keyed (schema id / semantic identity), not folder-name-keyed, so it survives a slug
 * rename without drifting from the real frozen contract. */
export function policyOsConfigShapeBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const breaches: BreachRecord[] = [];
  const schemaRel = `${POLICY_OS_CONFIG_ROOT}/🧬️schema`;
  if (!existsSync(join(repoRoot, schemaRel))) {
    breaches.push({
      id: `os-config-shape-missing-schema`,
      summary: `"${schemaRel}" is missing`,
      kind: "taxonomy/os-config-shape",
      scope: "os/config",
      priority: "high",
      reason: `The OS-level opening-preferences config facet (${POLICY_OS_CONFIG_SCHEMA_ID}) is a frozen C4 facet.`,
      solution: `Restore ${schemaRel}/ per contract §4.`,
    });
    return breaches;
  }
  for (const format of schemaFacetFormatEntries(schemaRel, taxonomy).map(([, f]) => f)) {
    const leafFilename = canonicalPrimaryFilenameForKind(format.fileKindId, taxonomy);
    if (existsSync(join(repoRoot, schemaRel, leafFilename))) continue;
    breaches.push({
      id: `os-config-shape-schema-leaf-${leafFilename}`,
      summary: `"${schemaRel}" is missing required schema leaf "${leafFilename}"`,
      kind: "taxonomy/os-config-shape",
      scope: "os/config",
      priority: "high",
      reason: `Every schemaFormats leaf for facet kind 🧬️data is frozen for ${POLICY_OS_CONFIG_SCHEMA_ID}.`,
      solution: `Add ${schemaRel}/${leafFilename}.`,
    });
  }
  const rootRust = policyReadFileSafe(repoRoot, schemaRel, (POLICY_RS_COMPONENT_LEAF_NAME));
  if (!rootRust.includes(POLICY_OS_CONFIG_SCHEMA_ID)) {
    breaches.push({
      id: `os-config-shape-schema-id`,
      summary: `"${schemaRel}/${POLICY_RS_COMPONENT_LEAF_NAME}" no longer declares the frozen schema id "${POLICY_OS_CONFIG_SCHEMA_ID}"`,
      kind: "taxonomy/os-config-shape",
      scope: "os/config",
      priority: "high",
      reason: "C4 froze the schema id os.config.opening; OpeningResolver and both hosts key off this exact string.",
      solution: `Restore the "${POLICY_OS_CONFIG_SCHEMA_ID}" schema id constant in ${schemaRel}/${POLICY_RS_COMPONENT_LEAF_NAME}.`,
    });
  }
  const mutationsRel = `${schemaRel}/🧬️mutations`;
  const componentFilename = canonicalFilenameForKind(taxonomy.mutationComponentFileKindId, taxonomy);
  const mutationDirs = policyReaddirSafe(repoRoot, mutationsRel).filter((e) => e.isDirectory);
  for (const mutationKind of POLICY_OS_CONFIG_MUTATION_KINDS) {
    const owner = mutationDirs.find((d) => {
      const component = policyReadFileSafe(repoRoot, mutationsRel, d.name, componentFilename);
      return component.includes(`kind: "${mutationKind}"`) || component.includes(`\"${mutationKind}\"`);
    });
    if (!owner) {
      breaches.push({
        id: `os-config-shape-mutation-missing-${mutationKind}`,
        summary: `"${mutationsRel}" is missing the frozen direct "${mutationKind}" mutation`,
        kind: "taxonomy/os-config-shape",
        scope: "os/config",
        priority: "high",
        reason: `C4 froze both mutation kinds (set-default-app, clear-default-app) on ${POLICY_OS_CONFIG_SCHEMA_ID}.`,
        solution: `Restore ${mutationsRel}/<slug>/${componentFilename} declaring the semantic identity "${mutationKind}".`,
      });
      continue;
    }
    const componentRel = `${mutationsRel}/${owner.name}/${componentFilename}`;
    if (!existsSync(join(repoRoot, componentRel))) {
      breaches.push({
        id: `os-config-shape-mutation-leaf-${componentRel}`,
        summary: `"${componentRel}" is missing`,
        kind: "taxonomy/os-config-shape",
        scope: "os/config",
        priority: "high",
        reason: "Every mutation folder directly owns its mandatory component file.",
        solution: `Add ${componentRel}.`,
      });
    }
  }
  return breaches;
}
//#endregion 🔧️PolicyRuleArtifactViewersEditors


//#region 🔧️PolicyRuleHandcraftedSpecP3
/** ⚖️P3/M4 handcrafted-grammar policy scanners (distinctness / generic / declared-use / wiring / empty examples). Exemptions shrink to empty by P6 — see ticket HANDCRAFTED-GRAMMAR-FOR-EVERY-ARTIFACT. */

const POLICY_HANDCRAFTED_SPEC_ROOTS = ["✏️s", "🧰️framework"] as const;
const POLICY_HANDCRAFTED_FACETS = ["🗣️dsl", "🔧️op", "🔺️diff", "🎒️pack", "📡️spr", "🧬️mutations"] as const;
const POLICY_GRAMMAR_SPEC_LEAF = canonicalPrimaryFilenameForKind("grammar-semio", loadCatalogTaxonomy());
const POLICY_PROTOCOL_SPEC_LEAF = canonicalPrimaryFilenameForKind("protocol-semio", loadCatalogTaxonomy());
const POLICY_RS_COMPONENT_LEAF = canonicalPrimaryFilenameForKind(loadCatalogTaxonomy().componentFileKinds["🦀️rust"]!, loadCatalogTaxonomy());
const POLICY_FAMILY_ROOT = "🧰️framework/🛍️products/💻️os/🔨️modules/🗣️dsl/👪️family";

/** 🧹Normalizes grammar/protocol headers so distinctness compares body shape, not dialect names. */
function policyNormalizeSpecContent(content: string): string {
  return content
    .split(/\r?\n/)
    .map((line) => {
      if (/^(grammar|protocol|extension|schema)\s+\S+/.test(line)) {
        return line.replace(/^(grammar|protocol|extension|schema)\s+\S+/, "$1 __NAME__");
      }
      if (/^start\s+\S+/.test(line)) return "start __START__";
      return line;
    })
    .join("\n");
}

function policyHashSpecContent(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

/** 🔎️Walks `relRoots` for files matching `pred`, skipping `POLICY_SKIP_DIRS` / dotted dirs and directories matching `skipDir`. */
function policyDiscoverGrammarAndProtocolSpecs(repoRoot: string): string[] {
  return policyWalkRelFiles(repoRoot, POLICY_HANDCRAFTED_SPEC_ROOTS, (_p, name) => name.endsWith(".grammar.semio") || name.endsWith(".protocol.semio"));
}

/**
 * 📏️Normalized-hash collision rule: two `.grammar.semio`/`.protocol.semio` under ✏️s/ or 🧰️framework/
 * must not share a body after dialect name/start normalization.
 */
function policySpecDistinctnessBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const byHash = new Map<string, string[]>();
  for (const relPath of policyDiscoverGrammarAndProtocolSpecs(repoRoot)) {
    const raw = policyReadFileSafe(repoRoot, relPath);
    const hash = policyHashSpecContent(policyNormalizeSpecContent(raw));
    const group = byHash.get(hash);
    if (group) group.push(relPath);
    else byHash.set(hash, [relPath]);
  }
  for (const [hash, group] of byHash) {
    if (group.length < 2) continue;
    const sorted = [...group].sort();
    for (let i = 0; i < sorted.length; i++) {
      for (let j = i + 1; j < sorted.length; j++) {
        const a = sorted[i]!;
        const b = sorted[j]!;
        if (POLICY_SPEC_DISTINCTNESS_EXEMPTIONS.has(a) || POLICY_SPEC_DISTINCTNESS_EXEMPTIONS.has(b)) continue;
        breaches.push({
          id: `spec-distinctness-${hash.slice(0, 12)}-${a}-${b}`,
          summary: `Normalized spec collision between "${a}" and "${b}"`,
          kind: "handcrafted-grammar/spec-distinctness",
          scope: a,
          priority: "high",
          reason: "Each artifact facet must own a distinct grammar/protocol body; shared stubs after name/start normalization are forbidden.",
          solution: `Handcraft distinct specs for both paths, then remove them from POLICY_SPEC_DISTINCTNESS_EXEMPTIONS.`,
        });
      }
    }
  }
  return breaches;
}

/**
 * 📏️Flags catch-all generic grammar shapes under ✏️s/ (prop IDENT=, untyped list/map/value with prop,
 * bare IDENT assign* shells, json/blob/base64/payload field names).
 */
function policyGenericSpecBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const grammars = policyWalkRelFiles(repoRoot, ["✏️s"], (_p, name) => name.endsWith(".grammar.semio"));
  for (const relPath of grammars) {
    if (POLICY_GENERIC_SPEC_EXEMPTIONS.has(relPath)) continue;
    const content = policyReadFileSafe(repoRoot, relPath);
    const reasons: string[] = [];
    if (/prop\s*=\s*IDENT\s*"="\s*\(/.test(content) || /prop\s*=\s*IDENT\s*=/.test(content)) {
      reasons.push("catch-all prop = IDENT");
    }
    const untyped: string[] = [];
    for (const name of ["list", "map", "value"] as const) {
      if (new RegExp(`^\\s*${name}\\s*=`, "m").test(content)) untyped.push(name);
    }
    if (/\bprop\b/.test(content) && untyped.length > 0) {
      reasons.push(`untyped catch-all production(s) ${untyped.join(", ")} with prop`);
    }
    if (/=\s*IDENT\s+assign\*\s+block\?/.test(content) || /=\s*IDENT\s+assign\*/.test(content)) {
      reasons.push("bare IDENT assign* statement shell");
    }
    if (/-(json|blob|base64|payload)"/.test(content) || /-(json|blob|base64|payload)\b/.test(content)) {
      reasons.push("json/blob/base64/payload field name");
    }
    if (reasons.length === 0) continue;
    breaches.push({
      id: `generic-spec-${relPath}`,
      summary: `"${relPath}" still uses generic grammar shape: ${reasons.join("; ")}`,
      kind: "handcrafted-grammar/generic-spec",
      scope: relPath,
      priority: "high",
      reason: "Artifact grammars must be domain-true; catch-all prop/list/map/value and bare statement shells are migration leftovers.",
      solution: `Handcraft ${relPath}, then remove it from POLICY_GENERIC_SPEC_EXEMPTIONS.`,
    });
  }
  return breaches;
}

/** 🔎️Loads `📖️family-*.grammar.semio` keyed by `family-*` id. */
function policyLoadFamilyFragments(repoRoot: string): Map<string, { relPath: string; productions: readonly string[] }> {
  const out = new Map<string, { relPath: string; productions: readonly string[] }>();
  const files = policyWalkRelFiles(repoRoot, [POLICY_FAMILY_ROOT], (_p, name) => name.startsWith("📖️family-") && name.endsWith(".grammar.semio"));
  for (const relPath of files) {
    const leaf = relPath.split("/").pop()!;
    const id = leaf.replace(/^📖️/, "").replace(/\.grammar\.semio$/, "");
    const content = policyReadFileSafe(repoRoot, relPath);
    const productions: string[] = [];
    for (const m of content.matchAll(/^([A-Za-z_][\w-]*)\s*=/gm)) {
      const name = m[1]!;
      if (name === "grammar" || name === "start" || name === "extension" || name === "dialect" || name === "use" || name === "schema" || name === "protocol") continue;
      productions.push(name);
    }
    out.set(id, { relPath, productions });
  }
  return out;
}

/**
 * 📏️Every `use family-X` must reference at least one production symbol from that family fragment.
 */
function policyDeclaredUseBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const families = policyLoadFamilyFragments(repoRoot);
  const grammars = policyWalkRelFiles(repoRoot, ["✏️s"], (_p, name) => name.endsWith(".grammar.semio"));
  for (const relPath of grammars) {
    if (POLICY_DECLARED_USE_EXEMPTIONS.has(relPath)) continue;
    const content = policyReadFileSafe(repoRoot, relPath);
    const uses = [...content.matchAll(/^use\s+(family-[\w-]+)/gm)].map((m) => m[1]!);
    if (uses.length === 0) continue;
    for (const fam of uses) {
      const frag = families.get(fam);
      if (!frag) {
        breaches.push({
          id: `declared-use-missing-${relPath}-${fam}`,
          summary: `"${relPath}" declares use ${fam} but no family fragment was found under ${POLICY_FAMILY_ROOT}`,
          kind: "handcrafted-grammar/declared-use",
          scope: relPath,
          priority: "high",
          reason: "Declared family imports must resolve to a 📖️family-*.grammar.semio fragment.",
          solution: `Add the family fragment or fix the use line, then remove ${relPath} from POLICY_DECLARED_USE_EXEMPTIONS if listed.`,
        });
        continue;
      }
      if (frag.productions.length === 0) continue;
      const referenced = frag.productions.some((prod) => new RegExp(`\b${prod.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\b`).test(content));
      if (referenced) continue;
      breaches.push({
        id: `declared-use-${relPath}-${fam}`,
        summary: `"${relPath}" declares use ${fam} but never references any production from ${frag.relPath}`,
        kind: "handcrafted-grammar/declared-use",
        scope: relPath,
        priority: "high",
        reason: "A use family-X line that never mentions a family production is dead wiring.",
        solution: `Reference at least one production from ${fam} in the artifact grammar, then remove ${relPath} from POLICY_DECLARED_USE_EXEMPTIONS.`,
      });
    }
  }
  return breaches;
}



function policyArtifactHasRegisterLanguage(repoRoot: string, artRel: string): boolean {
  const rsFiles = policyWalkRelFiles(repoRoot, [artRel], (_p, name) => name.endsWith(".rs"));
  for (const rel of rsFiles) {
    if (policyReadFileSafe(repoRoot, rel).includes("register_language")) return true;
  }
  return false;
}

/**
 * 📏️Facet `🦀️.rs` must `include_str!` its sibling grammar/protocol spec; artifacts with any
 * facet specs must call `register_language` somewhere under the artifact (engine preferred).
 */
function policySpecWiringBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const artRel of policyListPluginArtifactDirs(repoRoot)) {
    let hasAnySpec = false;
    for (const facet of POLICY_HANDCRAFTED_FACETS) {
      const facetRel = `${artRel}/${facet}`;
      if (!existsSync(join(repoRoot, facetRel))) continue;
      const grammarRel = `${facetRel}/${POLICY_GRAMMAR_SPEC_LEAF}`;
      const protocolRel = `${facetRel}/${POLICY_PROTOCOL_SPEC_LEAF}`;
      const hasGrammar = existsSync(join(repoRoot, grammarRel));
      const hasProtocol = existsSync(join(repoRoot, protocolRel));
      if (!hasGrammar && !hasProtocol) continue;
      hasAnySpec = true;
      const rsRel = `${facetRel}/${POLICY_RS_COMPONENT_LEAF}`;
      if (!existsSync(join(repoRoot, rsRel))) continue;
      if (POLICY_SPEC_WIRING_INCLUDE_EXEMPTIONS.has(rsRel)) continue;
      const rsBody = policyReadFileSafe(repoRoot, rsRel);
      const specs: string[] = [];
      if (hasGrammar) specs.push(POLICY_GRAMMAR_SPEC_LEAF);
      if (hasProtocol) specs.push(POLICY_PROTOCOL_SPEC_LEAF);
      for (const specLeaf of specs) {
        const wired = rsBody.includes("include_str!") && rsBody.includes(specLeaf);
        if (wired) continue;
        breaches.push({
          id: `spec-wiring-include-${rsRel}-${specLeaf}`,
          summary: `"${rsRel}" does not include_str! sibling spec "${specLeaf}"`,
          kind: "handcrafted-grammar/spec-wiring-include",
          scope: rsRel,
          priority: "high",
          reason: "Facet Rust components must embed their normative .grammar.semio/.protocol.semio via include_str!.",
          solution: `Add include_str!("…/${specLeaf}") to ${rsRel}, then remove it from POLICY_SPEC_WIRING_INCLUDE_EXEMPTIONS.`,
        });
      }
    }
    if (!hasAnySpec) continue;
    if (POLICY_SPEC_WIRING_REGISTER_EXEMPTIONS.has(artRel)) continue;
    if (policyArtifactHasRegisterLanguage(repoRoot, artRel)) continue;
    breaches.push({
      id: `spec-wiring-register-${artRel}`,
      summary: `Artifact "${artRel}" has facet specs but never calls register_language`,
      kind: "handcrafted-grammar/spec-wiring-register",
      scope: artRel,
      priority: "high",
      reason: ("Artifacts that ship grammar/protocol specs must register the language with the shared DSL host (typically in ⚙️engine/" + POLICY_RS_COMPONENT_LEAF_NAME + ")."),
      solution: `Call register_language from the artifact engine (or another artifact .rs), then remove ${artRel} from POLICY_SPEC_WIRING_REGISTER_EXEMPTIONS.`,
    });
  }
  return breaches;
}

/**
 * 📏️ Any asset under `🖼️assets/` inside `📚️examples` must carry real payload (size > 64), covering every
 * kind suffix (`.dsl.semio`, `.op.semio`, `.spr.semio`, `.pack.semio`, `.diff.semio`, `.cmd.semio`) and media.
 */
/**
 * 📏️Empty/stub `.semio` under `📚️examples/** /🖼️assets/` (all kinds) — size ≤ 64 is a breach.
 * `POLICY_EMPTY_EXAMPLE_EXEMPTIONS` stays empty.
 */
function policyEmptyExampleBreaches(repoRoot: string): BreachRecord[] {
  const taxonomy = loadTaxonomy();
  const assetsDir = taxonomy.exampleAssetsDirName;
  const breaches: BreachRecord[] = [];
  const files = policyWalkRelFiles(repoRoot, [""], (relPath, name) => {
    if (!name.endsWith(".semio")) return false;
    const norm = relPath.replaceAll("\\", "/");
    if (!(norm.includes("/📚️examples/") || norm.startsWith("📚️examples/"))) return false;
    return norm.includes(`/${assetsDir}/`);
  });
  for (const relPath of files) {
    if (POLICY_EMPTY_EXAMPLE_EXEMPTIONS.has(relPath)) continue;
    let size = 0;
    try {
      size = statSync(join(repoRoot, relPath)).size;
    } catch {
      continue;
    }
    if (size > 64) continue;
    breaches.push({
      id: `empty-example-${relPath}`,
      summary: `"${relPath}" is an empty/envelope-only example asset (${size} bytes ≤ 64)`,
      kind: "handcrafted-grammar/empty-example",
      scope: relPath,
      priority: "high",
      reason: "Example `.semio` assets under 🖼️assets/ must include a real payload, not just an empty envelope or stub.",
      solution: `Seed a non-empty example at ${relPath}, then remove it from POLICY_EMPTY_EXAMPLE_EXEMPTIONS.`,
    });
  }
  return breaches;
}

function policyGenericCodecDeriveBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const files = policyWalkRelFiles(repoRoot, ["✏️s/🔌️plugins"], (relPath, name) => {
    return relPath.includes("/🗿️artifacts/") && name.endsWith(".rs");
  });
  const banned = [
    { re: /dsl::__rt::parse_document_record|dsl::__rt::print_document_record|dsl::__rt::parse_inline_record|dsl::__rt::print_inline_record/g, label: "__rt codec wrapper" },
    { re: /dsl::op_rt::|store::op_rt::/g, label: "op_rt generic OpBinary" },
  ];
  for (const relPath of files) {
    const content = policyReadFileSafe(repoRoot, relPath);
    for (const { re, label } of banned) {
      re.lastIndex = 0;
      let match: RegExpExecArray | null;
      while ((match = re.exec(content)) !== null) {
        const before = content.slice(0, match.index);
        const line = before.split(/\r?\n/).length;
        breaches.push({
          id: `generic-codec-runtime-${relPath}-${line}`,
          summary: `Residual generic codec path (${label}) in "${relPath}" (line ${line})`,
          kind: "handcrafted-grammar/generic-codec-derive",
          scope: relPath,
          line,
          priority: "high",
          reason: "P6 deleted derive-emitted DocumentDsl/OpText/DocumentPack/OpBinary and their __rt/op_rt entrypoints; artifacts must use handcrafted codecs.",
          solution: `Replace ${label} usage in ${relPath} with the artifact's handcrafted DocumentDsl/OpText/DocumentPack/OpBinary impl.`,
        });
      }
    }
  }
  return breaches;
}

/** 🔗 Cumulative `#[path]` targets declared by one `🦀️.rs` (absolute resolved paths). */
function policyCollectGluePathTargets(glueAbs: string): Set<string> {
  const declared = new Set<string>();
  if (!existsSync(glueAbs)) return declared;
  const libDir = dirname(glueAbs);
  const libText = readFileSync(glueAbs, "utf8");
  const baseStack: string[] = [libDir];
  let pendingPath: string | null = null;
  for (const rawLine of libText.split(/\r?\n/)) {
    const line = rawLine.trim();
    const pathMatch = line.match(/#\[path\s*=\s*"([^"]+)"\]/);
    if (pathMatch) {
      pendingPath = pathMatch[1] ?? null;
      continue;
    }
    const modMatch = line.match(/^(?:pub\s+)?mod\s+([A-Za-z_][A-Za-z0-9_]*)/);
    if (modMatch) {
      const modName = modMatch[1]!;
      const base = baseStack[baseStack.length - 1] ?? libDir;
      let resolved: string;
      if (pendingPath === null) {
        resolved = join(base, modName);
      } else if (pendingPath === ".") {
        resolved = base;
      } else {
        resolved = join(base, pendingPath);
      }
      pendingPath = null;
      const asFile = resolved.endsWith(".rs") ? resolved : `${resolved}.rs`;
      const asModFile = join(resolved, "mod.rs");
      if (existsSync(asFile)) declared.add(resolve(asFile));
      else if (existsSync(asModFile)) declared.add(resolve(asModFile));
      else declared.add(resolve(asFile));
      if (line.includes("{")) baseStack.push(resolved.endsWith(".rs") ? dirname(resolved) : resolved);
      continue;
    }
    pendingPath = null;
    const opens = (line.match(/\{/g) ?? []).length;
    const closes = (line.match(/\}/g) ?? []).length;
    for (let i = 0; i < opens; i++) baseStack.push(baseStack[baseStack.length - 1] ?? libDir);
    for (let i = 0; i < closes; i++) {
      if (baseStack.length > 1) baseStack.pop();
    }
  }
  return declared;
}

/**
 * ☠️ Any `.rs` under `📚️examples` must be reachable via `#[path]` from a `🦀️.rs` — dead definition
 * or test shims are forbidden.
 */
function policyDeadExampleLeafBreaches(repoRoot: string, crates: readonly PolicyCrateRef[]): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const reachable = new Set<string>();
  const owners = [...new Set(crates.filter((crate) => crate.shape === "taxonomy").map((crate) => crate.ownerRel).filter(Boolean))];
  const glueRoots = owners.length > 0 ? owners : ["✏️s/🔌️plugins"];
  for (const crate of crates) {
    if (crate.shape !== "taxonomy") continue;
    for (const target of policyCollectGluePathTargets(join(repoRoot, crate.libRelPath))) reachable.add(target);
  }
  for (const glueRel of policyWalkRelFiles(repoRoot, glueRoots, (_p, name) => name === "🦀️.rs")) {
    for (const target of policyCollectGluePathTargets(join(repoRoot, glueRel))) reachable.add(target);
  }
  const fw = readdirSync(repoRoot).find((name) => name.endsWith("framework"));
  const exampleRoots = owners.length > 0 ? owners : fw ? ["✏️s/🔌️plugins", fw] : ["✏️s/🔌️plugins"];
  const exampleRs = policyWalkRelFiles(repoRoot, exampleRoots, (relPath, name) => {
    if (!name.endsWith(".rs")) return false;
    return relPath.replaceAll("\\", "/").includes("/📚️examples/");
  });
  for (const relPath of exampleRs) {
    const abs = resolve(join(repoRoot, relPath));
    if (reachable.has(abs)) continue;
    breaches.push({
      id: `dead-example-leaf-${relPath}`,
      summary: `"${relPath}" is not reachable via #[path] from any 🦀️.rs`,
      kind: "taxonomy/dead-example-leaf",
      scope: relPath,
      priority: "high",
      reason: "Every .rs under 📚️examples must be wired from the plugin 🦀️.rs (definition leaf or cfg(test) test leaf).",
      solution: `Add a #[path] mod declaration for ${relPath} under //#region 📚️Examples in the owning 🦀️.rs, or delete the dead file.`,
    });
  }
  return breaches;
}

/** ⚖️Aggregates all P3/M4 handcrafted-grammar high-priority scanners for policy + verify gate. */
function policyHandcraftedSpecP3Breaches(repoRoot: string): BreachRecord[] {
  return [
    ...policySpecDistinctnessBreaches(repoRoot),
    ...policyGenericSpecBreaches(repoRoot),
    ...policyDeclaredUseBreaches(repoRoot),
    ...policySpecWiringBreaches(repoRoot),
    ...policyEmptyExampleBreaches(repoRoot),
    ...policyGenericCodecDeriveBreaches(repoRoot),
  ];
}

/** 📏️Every concrete mutation directory owns one authoritative direct Rust component. */
function policyMutationDirectOwnerBreaches(repoRoot: string, mutationRoots: readonly string[] = policyFindAllMutationsDirs(repoRoot)): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const mutationsRel of mutationRoots) {
    const artRel = policyArtifactRootOfMutationsDir(mutationsRel);
    for (const mutName of policyListMutationDirs(repoRoot, mutationsRel)) {
      const mutRel = `${mutationsRel}/${mutName}`;
      const directRel = `${mutRel}/${POLICY_RS_COMPONENT_LEAF_NAME}`;
      if (existsSync(join(repoRoot, directRel))) continue;
      breaches.push({
        id: `mutation-direct-owner-${mutRel}`,
        summary: `"${mutRel}" has no direct ${POLICY_RS_COMPONENT_LEAF_NAME}`,
        kind: "mutation/direct-owner",
        scope: artRel,
        priority: "high",
        reason: "Every concrete mutation is represented by exactly one direct semantic folder whose component is authoritative.",
        solution: `Move the concrete implementation to ${directRel}; optional diff, inverse, plan, text, binary, and tests remain child facets.`,
      });
    }
  }
  return breaches;
}

/**
 * 📏️A direct mutation component owns its semantic descriptor and mutation implementation.
 */
function policyMutationImplPresenceBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const mutationsRel of policyFindAllMutationsDirs(repoRoot)) {
    const artRel = policyArtifactRootOfMutationsDir(mutationsRel);
    for (const mutName of policyListMutationDirs(repoRoot, mutationsRel)) {
      const mutRel = `${mutationsRel}/${mutName}`;
      const rsRel = `${mutRel}/${POLICY_RS_COMPONENT_LEAF_NAME}`;
      const abs = join(repoRoot, rsRel);
      if (!existsSync(abs)) continue;
      const content = readFileSync(abs, "utf8");
      if (/\bimpl\b[^\n{]*\b(?:Mutation|MutationKind|CompositeMutationKind)\b/.test(content) && /\b(?:SEMANTICS|DESCRIPTOR)\b/.test(content)) continue;
      breaches.push({
        id: `mutation-impl-missing-${rsRel}`,
        summary: `"${rsRel}" does not own both mutation behavior and a semantic descriptor`,
        kind: "mutation/behavior-ownership",
        scope: artRel,
        priority: "high",
        reason: "The direct leaf is the visible source of semantic identity and apply/diff/inverse participation.",
        solution: `Define the leaf payload, descriptor, and MutationKind/Mutation implementation in ${rsRel}.`,
      });
    }
  }
  return breaches;
}

/** 🔗️Plugin roots that may declare runtime dependencies: `✏️s/🔌️plugins/<plugin>` and its `🧩️extensions/<ext>`. */
function policyDependencyOwnerRoots(repoRoot: string): readonly string[] {
  const roots: string[] = [];
  for (const plugin of policyReaddirSafe(repoRoot, "✏️s/🔌️plugins").filter((e) => e.isDirectory && !e.name.startsWith("."))) {
    const pluginRel = `✏️s/🔌️plugins/${plugin.name}`;
    roots.push(pluginRel);
    for (const ext of policyReaddirSafe(repoRoot, `${pluginRel}/🧩️extensions`).filter((e) => e.isDirectory && !e.name.startsWith("."))) {
      roots.push(`${pluginRel}/🧩️extensions/${ext.name}`);
    }
  }
  return roots;
}

/**
 * 🔗️Component leaves that belong to `ownerRel` ITSELF, excluding any nested `🧩️extensions/<ext>/`
 * subtree — an extension is its own dependency owner (it appears separately in
 * [[policyDependencyOwnerRoots]]), so folding its files into its parent plugin's walk made the parent
 * inherit the extension's `.depends_on(...)` and demand a Cargo dependency the parent never needs. A
 * plugin that hosts an extension declaring `.depends_on("cad")` is not itself a dependent of `cad`.
 */
function policyOwnerOwnComponentFiles(repoRoot: string, ownerRel: string): string[] {
  return policyWalkRelFiles(
    repoRoot,
    [ownerRel],
    (_relPath, name) => name === POLICY_RS_COMPONENT_LEAF_NAME,
    (_relDir, name) => name === "🧩️extensions",
  );
}

/** 🔗️An owner's DECLARED runtime plugin dependencies — `[package.metadata.semio].depends-on` plus,
 * for an extension, its `extends` host (contract freeze §4 rule 1 makes the host `dependsOn[0]`).
 * Deliberately NOT the crate's `[dependencies]`: a `semio-s-plugin-<id>` Cargo line is a build-time
 * rlib link (codecs, schema types) that says nothing about needing `<id>`'s own actor loaded. */
function policySemioMetadataDependsOnIds(repoRoot: string, ownerRel: string): { readonly declared: Set<string>; readonly extendsHost?: string } {
  const manifest = policyReadFileSafe(repoRoot, `${ownerRel}/📦️packages/🦀️rust/Cargo.toml`);
  const semioBlock = manifest.split(/(?=\n\[)/).find((block) => block.trimStart().startsWith("[package.metadata.semio]")) ?? "";
  const extendsHost = semioBlock.match(/^extends\s*=\s*"([a-z0-9-]+)"/m)?.[1];
  const declared = new Set<string>();
  const list = semioBlock.match(/^depends-on\s*=\s*\[([^\]]*)\]/m)?.[1] ?? "";
  for (const match of list.matchAll(/"([a-z0-9-]+)"/g)) declared.add(match[1]!);
  return { declared, extendsHost };
}

/**
 * 📏️The one declared runtime-dependency set of a plugin has two co-located mirrors that must agree:
 * `.depends_on("x", …)` on the owner's builder (`🦀️.rs`, the wire `PluginManifest.dependencies` the
 * host's load order, version checks and contribution gates read) and
 * `[package.metadata.semio].depends-on` in its Cargo manifest (what the plugin registry generator
 * reads, since it runs before any wasm build could emit a descriptor). Both directions are checked so
 * neither half can drift. An extension's `extends` host counts as declared on the metadata side.
 *
 * 🚫️ A Cargo `[dependencies]` link on a sibling plugin crate is NOT a runtime dependency and is not
 * examined here: deriving the runtime graph from library links pulled `stdio` (linked by ~every
 * plugin purely for in-process codecs) into every browser session's load set.
 */
export function policyPluginDependencyParityBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const ownerRel of policyDependencyOwnerRoots(repoRoot)) {
    const declared = new Set<string>();
    for (const relPath of policyOwnerOwnComponentFiles(repoRoot, ownerRel)) {
      for (const match of policyReadFileSafe(repoRoot, relPath).matchAll(/\.depends_on\s*\(\s*"([a-z0-9-]+)"/g)) {
        declared.add(match[1]!);
      }
    }
    const metadata = policySemioMetadataDependsOnIds(repoRoot, ownerRel);
    const ownId = policyStripEmoji(ownerRel.split("/").pop() ?? "");
    for (const id of declared) {
      if (metadata.declared.has(id) || id === metadata.extendsHost) continue;
      breaches.push({
        id: `plugin-dependency-undeclared-metadata-${ownerRel}-${id}`,
        summary: `"${ownerRel}" declares .depends_on("${id}") with no matching [package.metadata.semio].depends-on entry`,
        kind: "plugin-dependency/parity",
        scope: ownerRel,
        priority: "high",
        reason: "The plugin registry is generated from Cargo metadata before any wasm build exists, so a runtime dependency only the builder knows about is missing from every load order and dev session closure.",
        solution: `Add "${id}" to depends-on in ${ownerRel}/📦️packages/🦀️rust/Cargo.toml's [package.metadata.semio].`,
      });
    }
    for (const id of metadata.declared) {
      if (id === ownId || declared.has(id)) continue;
      breaches.push({
        id: `plugin-dependency-undeclared-runtime-${ownerRel}-${id}`,
        summary: `"${ownerRel}" declares depends-on = ["${id}"] without declaring .depends_on("${id}")`,
        kind: "plugin-dependency/parity",
        scope: ownerRel,
        priority: "high",
        reason: "The host builds its load order, version checks and contribution gates from the runtime manifest — a dependency the manifest never mentions is invisible to all three.",
        solution: `Add .depends_on("${id}", …) to the plugin/extension builder in ${ownerRel}.`,
      });
    }
  }
  return breaches;
}

/**
 * 📏️Every `ArtifactContribution::builder("s.<owner>.<artifact>")` must target an artifact whose
 * owning plugin the contributor declares as a direct dependency — contributing onto a plugin you do
 * not depend on is exactly the unowned-registration this ticket's contract forbids.
 */
export function policyContributionTargetBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const ownerRel of policyDependencyOwnerRoots(repoRoot)) {
    const declared = new Set<string>();
    const targets = new Map<string, string>();
    for (const relPath of policyOwnerOwnComponentFiles(repoRoot, ownerRel)) {
      const content = policyReadFileSafe(repoRoot, relPath);
      for (const match of content.matchAll(/\.depends_on\s*\(\s*"([a-z0-9-]+)"/g)) declared.add(match[1]!);
      for (const match of content.matchAll(/ArtifactContribution::builder\s*\(\s*"([^"]+)"/g)) targets.set(match[1]!, relPath);
    }
    for (const [kind, relPath] of targets) {
      const owner = kind.split(".")[1];
      if (!owner) {
        breaches.push({
          id: `contribution-target-ungrammatical-${relPath}-${kind}`,
          summary: `"${relPath}" contributes to "${kind}", which is not a canonical s.<plugin>.<artifact> kind`,
          kind: "plugin-dependency/contribution-target",
          scope: ownerRel,
          priority: "high",
          reason: "A contribution target must name its owning plugin so the dependency gate can resolve it.",
          solution: `Use the canonical kind id of the target artifact in ${relPath}.`,
        });
        continue;
      }
      if (declared.has(owner)) continue;
      breaches.push({
        id: `contribution-target-undeclared-${ownerRel}-${kind}`,
        summary: `"${ownerRel}" contributes to "${kind}" without declaring .depends_on("${owner}")`,
        kind: "plugin-dependency/contribution-target",
        scope: ownerRel,
        priority: "high",
        reason: "Mutations and inferences may only be registered onto artifacts of a directly declared dependency.",
        solution: `Add .depends_on("${owner}", …) to the plugin/extension builder in ${ownerRel}.`,
      });
    }
  }
  return breaches;
}

/**
 * 📏️Every `🔧️op/*.grammar.semio` must declare `start mutation` (production `mutation =` follows in fan-out).
 */
function policyOpGrammarStartMutationBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const grammars = policyWalkRelFiles(repoRoot, ["✏️s"], (relPath, name) => {
    if (!name.endsWith(".grammar.semio")) return false;
    return relPath.replaceAll("\\", "/").includes(`/${POLICY_OP_FACET}/`);
  });
  for (const relPath of grammars) {
    const content = policyReadFileSafe(repoRoot, relPath);
    if (/^start\s+mutation\b/m.test(content)) continue;
    const legacy = /^start\s+operation\b/m.test(content);
    breaches.push({
      id: `op-grammar-start-mutation-${relPath}`,
      summary: legacy
        ? `"${relPath}" still declares start operation — must be start mutation`
        : `"${relPath}" is missing start mutation`,
      kind: "mutation-migration/op-grammar-start",
      scope: relPath,
      priority: "high",
      reason: "The 🔧️op grammar start symbol is the Mutation production (`start mutation`); OpText/OpBinary brand stays.",
      solution: `Change the start line in ${relPath} to "start mutation" (and rename production operation = to mutation =).`,
    });
  }
  return breaches;
}

/** 🏘️ Concrete mutation emojis are compared within their actual sibling owner, including declared domains. */
function policyMutationEmojiUniquenessBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const mutationsRel of policyFindAllMutationsDirs(repoRoot)) {
    const artRel = policyArtifactRootOfMutationsDir(mutationsRel);
    const seen = new Map<string, string>();
    for (const mutName of policyListMutationDirs(repoRoot, mutationsRel)) {
      const emoji = policyLeadingEmojiPrefix(posix.basename(mutName));
      if (!emoji) {
        breaches.push({
          id: `mutation-emoji-missing-${mutationsRel}/${mutName}`,
          summary: `"${mutationsRel}/${mutName}" has no leading emoji prefix`,
          kind: "mutation-migration/emoji-uniqueness",
          scope: artRel,
          priority: "medium",
          reason: "Each concrete mutation directory must pick a unique emoji among its siblings.",
          solution: `Rename ${mutName} to include a unique emoji prefix (e.g. ➕️objects-add).`,
        });
        continue;
      }
      const siblingKey = `${posix.dirname(mutName)}\0${emoji}`;
      const prev = seen.get(siblingKey);
      if (prev) {
        breaches.push({
          id: `mutation-emoji-dup-${artRel}-${emoji}-${mutName}`,
          summary: `"${mutationsRel}/${mutName}" reuses emoji "${emoji}" already used by "${prev}"`,
          kind: "mutation-migration/emoji-uniqueness",
          scope: artRel,
          priority: "medium",
          reason: "Specific mutation dir emojis must be unique among siblings.",
          solution: `Give ${mutName} a different emoji than ${prev}.`,
        });
        continue;
      }
      seen.set(siblingKey, mutName);
    }
  }
  return breaches;
}

/** 🔍️Every repository-owned `🧬️mutations` facet, with opaque/build/cache roots excluded before access. */
function policyRepositoryOwnedRoots(): string[] {
  const configured = Object.entries(loadTaxonomy().areas ?? {})
    .filter(([, state]) => state === "clean")
    .map(([area]) => area);
  const candidates = [...new Set(["✏️s", "🧰️framework", "🌎️hub", "♻️mit-bestand", ...configured])]
    .filter((candidate) => candidate !== "compose" && !candidate.startsWith("compose/"));
  return candidates
    .filter((candidate) => !candidates.some((other) => other !== candidate && candidate.startsWith(`${other}/`)))
    .sort();
}

/**
 * 📏️SEMANTIC-MUTATIONS-OVERHAUL rule 1: every repository-owned `.rs` file under a
 * `🧬️mutations/` facet or a `🎮️commands/` app-command dir must not reference the banned generic mutation
 * vocabulary the new `SemanticDescriptor`/`MutationKind`/`#[derive(dsl_derive::Mutations)]` mechanism
 * (see `🧰️framework/…/📡️spr/🎮️command/🦀️.rs`'s `🔖️Semantics` region) replaces: `SetSnapshot`
 * (the whole-document escape hatch), `NoMutation` (the sentinel sibling), and `CollectionMutation<`/`::`
 * (the generic collection wrapper, worst-offender count ~70 in one facet). `Set[A-Z]\w*` dispatch-enum
 * variant names are additionally flagged at `"medium"`; the generic escape hatches have no
 * suppression or exception mechanism.
 */
/**
 * 🚫️High-priority banned generic-vocabulary tokens: the whole-document escape hatch, the sentinel, and the
 * generic collection wrapper. Deliberately substring (no `\b` word boundary) matching the
 * seeding grep exactly, so derived type names like `SetSnapshotDiff`/`SetSnapshotMutation` still count —
 * they're just as much banned vocabulary as the bare identifier.
 */
const POLICY_SEMANTIC_VOCABULARY_HIGH_TOKENS: readonly { label: string; re: RegExp }[] = [
  { label: "SetSnapshot", re: /SetSnapshot/ },
  { label: "NoMutation", re: /NoMutation/ },
  { label: "CollectionMutation<...>", re: /CollectionMutation(<|::)/ },
];

/** 🏷️Every `.rs` file under a `🧬️mutations/` facet or a `🎮️commands/` app-command dir, repo-wide. */
function policyListSemanticVocabularyScanFiles(repoRoot: string): string[] {
  return policyWalkRelFiles(repoRoot, policyRepositoryOwnedRoots(), (relPath, name) => {
    if (!name.endsWith(".rs")) return false;
    const norm = relPath.replaceAll("\\", "/");
    return norm.includes(`/${POLICY_MUTATIONS_FACET}/`) || norm.includes("/🎮️commands/");
  });
}

function policySemanticVocabularyBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const relPath of policyListSemanticVocabularyScanFiles(repoRoot)) {
    const content = policyReadFileSafe(repoRoot, relPath);
    const hitTokens = POLICY_SEMANTIC_VOCABULARY_HIGH_TOKENS.filter((t) => t.re.test(content)).map((t) => t.label);
    if (hitTokens.length > 0) {
      breaches.push({
        id: `semantic-vocabulary-banned-${relPath}`,
        summary: `"${relPath}" references banned generic mutation vocabulary: ${hitTokens.join(", ")}`,
        kind: "mutation-migration/semantic-vocabulary",
        scope: relPath,
        priority: "high",
        reason: "SetSnapshot/NoMutation/CollectionMutation are generic escape hatches replaced by explicit direct semantic mutations.",
        solution: `Replace ${hitTokens.join(", ")} in ${relPath} with explicit semantic MutationKind payloads.`,
      });
    }
    const bareSetVariants = [...new Set([...content.matchAll(/\bSet[A-Z]\w*/g)].map((m) => m[0]))].filter((name) => name !== "SetSnapshot");
    if (bareSetVariants.length > 0) {
      breaches.push({
        id: `semantic-vocabulary-bare-set-${relPath}`,
        summary: `"${relPath}" declares ${bareSetVariants.length} bare Set* identifier(s): ${bareSetVariants.slice(0, 6).join(", ")}${bareSetVariants.length > 6 ? ", …" : ""}`,
        kind: "mutation-migration/semantic-vocabulary",
        scope: relPath,
        priority: "medium",
        reason: "Set* is the generic verb this overhaul retires in favor of the closed APPROVED_VERBS vocabulary (rename/change/move/flatten/connect/group/…) — advisory (unallowlisted) until the fan-out wave rewrites dispatch enums.",
        solution: `Rename the Set* variant(s) in ${relPath} to a semantic verb-entity name backed by a MutationKind payload.`,
      });
    }
  }
  return breaches;
}

function policyMutationDispatchCoverageBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const mutationsRel of policyFindAllMutationsDirs(repoRoot)) {
    const dispatchRel = `${mutationsRel}/${POLICY_RS_COMPONENT_LEAF_NAME}`;
    if (!existsSync(join(repoRoot, dispatchRel))) continue;
    const variantNames = new Set(policyMutationEnumVariantNames(policyReadFileSafe(repoRoot, dispatchRel)));
    if (variantNames.size === 0) continue;
    const triadPascalNames = new Set(policyListMutationDirs(repoRoot, mutationsRel).map((dir) => policyKebabToPascal(policyMutationSemanticIdentity(mutationsRel, dir))));
    const uncoveredVariants = [...variantNames].filter((v) => !triadPascalNames.has(v));
    const orphanTriads = [...triadPascalNames].filter((t) => !variantNames.has(t));
    if (uncoveredVariants.length === 0 && orphanTriads.length === 0) continue;
    breaches.push({
      id: `mutation-dispatch-coverage-${dispatchRel}`,
      summary: `"${dispatchRel}" dispatch variants and ${mutationsRel} triad dirs disagree: ${uncoveredVariants.length} variant(s) with no triad dir, ${orphanTriads.length} triad dir(s) with no variant`,
      kind: "mutation-migration/dispatch-coverage",
      scope: mutationsRel,
      priority: "medium",
      reason: "Once the fan-out wave adopts #[derive(dsl_derive::Mutations)], every dispatch variant must be a single-field tuple wrapping exactly one triad dir's MutationKind payload — advisory until then.",
      solution: `Reconcile ${dispatchRel}'s enum variants with the triad dirs under ${mutationsRel} (rename to match, or add/remove triad dirs).`,
    });
  }
  return breaches;
}

/**
 * 📏️SEMANTIC-MUTATIONS-OVERHAUL rule 3 (`policyMutationTsMirrorBreaches`): flags any `.ts` leaf anywhere
 * under a `🧬️mutations/` facet whose content is trivially `export {};` (or empty) — near-universal today
 * (triad `.ts` leaves were scaffolded as stubs, see `policyIsConstitutionalTsFacadePath`'s explicit tolerance for this exact shape),
 * so this stays `"low"` advisory with no allowlist rather than seeding ~1000+ file paths for a finding that
 * blocks nothing; it exists so a real TS mirror rollout has a tracked signal to burn down file-by-file.
 */
function policyMutationTsMirrorBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const tsFiles = policyWalkRelFiles(repoRoot, ["✏️s"], (relPath, name) => name === POLICY_TS_COMPONENT_LEAF && relPath.replaceAll("\\", "/").includes(`/${POLICY_MUTATIONS_FACET}/`));
  for (const relPath of tsFiles) {
    const stripped = policyReadFileSafe(repoRoot, relPath)
      .replace(/\/\*[\s\S]*?\*\//g, "")
      .replace(/\/\/.*$/gm, "")
      .trim();
    if (stripped !== "" && stripped !== "export {};") continue;
    breaches.push({
      id: `mutation-ts-mirror-stub-${relPath}`,
      summary: `"${relPath}" is a trivial "export {};" stub with no real TS mirror`,
      kind: "mutation-migration/ts-mirror",
      scope: relPath,
      priority: "low",
      reason: "A triad leaf's TS mirror should eventually re-export the same MutationKind payload shape as its Rust sibling, not stay an empty stub.",
      solution: `Give ${relPath} real content mirroring its ${POLICY_RS_COMPONENT_LEAF_NAME} sibling once the DSL TS codegen for this triad lands.`,
    });
  }
  for (const rsRel of policyWalkRelFiles(repoRoot, ["✏️s"], (relPath, name) => name === POLICY_RS_COMPONENT_LEAF_NAME && relPath.replaceAll("\\", "/").includes(`/${POLICY_MUTATIONS_FACET}/`))) {
    const tsRel = `${rsRel.slice(0, rsRel.lastIndexOf("/"))}/${POLICY_TS_COMPONENT_LEAF}`;
    if (existsSync(join(repoRoot, tsRel))) continue;
    breaches.push({
      id: `mutation-ts-mirror-absent-${tsRel}`,
      summary: `"${rsRel}" has no ${POLICY_TS_COMPONENT_LEAF} mirror beside it at all`,
      kind: "mutation-migration/ts-mirror",
      scope: tsRel,
      priority: "low",
      reason: "An ABSENT mirror is invisible to the stub scan above, so a facet that never scaffolded its .ts leaves looked cleaner than one that did — this half closes that blind spot.",
      solution: `Create ${tsRel} mirroring its ${POLICY_RS_COMPONENT_LEAF_NAME} sibling's MutationKind payload shape.`,
    });
  }
  return breaches;
}
//#endregion 🧬️DirectMutationPolicies

/**
 * 🎮️App command folders must be one semantically named command (verb-noun kebab), matching
 * `🧬️mutations/<emoji><verb>-<noun>/`. Noun buckets (`✍️text`, `🗂️selection`, `🗣️locale`) are
 * architecture violations. Held at `"medium"` while ticket `26/08/13/SEMANTIC-COMMAND-NAMES`
 * fans out; graduate to `"high"` once every plugin leaf is 1:1.
 */
const POLICY_COMMAND_VERBS = new Set<string>([
  "create", "delete", "insert", "remove", "add", "rename", "change", "update", "move",
  "drag", "resize", "rotate", "scale", "reorder", "edit", "replace", "duplicate",
  "connect", "disconnect", "bind", "unbind", "group", "ungroup", "flatten", "unflatten",
  "split", "merge", "extract", "inline", "clear", "fix", "toggle", "apply", "set",
  "format", "open", "load", "save", "import", "export", "lint", "request", "select",
  "hover", "evaluate", "run", "retry", "calibrate", "place", "commit", "input",
  "submit", "abort", "patch", "paint", "nudge", "reset", "focus", "step", "query",
  "fill", "snap", "ingest", "evaluate",
]);

function policyCommandFolderSemanticBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const walk = (relDir: string): void => {
    for (const ent of policyReaddirSafe(repoRoot, relDir)) {
      if (!ent.isDirectory || ent.name.startsWith(".")) continue;
      const childRel = relDir ? `${relDir}/${ent.name}` : ent.name;
      if (ent.name === "🎮️commands") {
        for (const cmd of policyReaddirSafe(repoRoot, childRel)) {
          if (!cmd.isDirectory) continue;
          const folder = cmd.name;
          const emoji = policyLeadingEmojiPrefix(folder);
          const slug = emoji ? folder.slice(emoji.length) : folder;
          const verb = slug.split("-")[0] ?? slug;
          if (POLICY_COMMAND_VERBS.has(verb)) continue;
          breaches.push({
            id: `command-folder-semantic-${childRel}/${folder}`,
            summary: `"${childRel}/${folder}" is a noun bucket, not a semantic command`,
            kind: "taxonomy/command-folder-semantic",
            scope: childRel,
            priority: "medium",
            reason: "Each 🎮️commands/ leaf must be one command named like a mutation (verb-noun kebab, e.g. 📝️text-edit). Grouping under domain nouns (text, selection, locale, camera) is banned.",
            solution: `Split ${childRel}/${folder} into one folder per command using an approved verb prefix (${[...POLICY_COMMAND_VERBS].slice(0, 8).join(", ")}, …).`,
          });
        }
        continue;
      }
      if (ent.name === "target" || ent.name === "node_modules") continue;
      walk(childRel);
    }
  };
  walk("✏️s");
  return breaches;
}

/** ⚖️Aggregates Wave 2b mutation / ArtifactEngine / op-grammar scanners. */
function policyMutationArtifactEngineBreaches(repoRoot: string): BreachRecord[] {
  return [
    ...policyMutationStructuralBreaches(repoRoot),
    ...policyOpGrammarStartMutationBreaches(repoRoot),
    ...policyMutationEmojiUniquenessBreaches(repoRoot),
    ...policySemanticVocabularyBreaches(repoRoot),
    ...policyCommandFolderSemanticBreaches(repoRoot),
  ];
}
//#endregion 🔧️PolicyRuleMutationArtifactEngines

//#region 🔧️PolicyRuleMutationOutcomeMergePolicy
/**
 * 🎫️ `26/08/16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS` C2/C4/C10 gates: every
 * `🔺️diff` leaf must report through `protocol::MutationOutcome<D>` using only the 9 frozen codes
 * (`📋️contract-freeze.md` §C2 plus the two state-dependent `Error` codes `mutation.target-referenced` and
 * `mutation.target-mismatch` added 2026-09-30, ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING), `validate` is deleted everywhere, `Severity::Hint` is gone, the CRDT
 * merge-strategy/conflict-rule vocabulary reaches zero, `MergePolicy`'s 3 variants mirror across all 4
 * surfaces that spell them, and the dsl derive macro's package glue mounts its one owner implementation.
 * All sixteen rules (the seven above plus the diff-only rules R8–R16 of ticket `26/10/08/DIFF-ONLY-MUTATIONS-WITH-CENTRAL-APPLY-AND-DIFF-SUMMING-INVERSES`) read one shared git-visible inventory (`policyMutationLawInventory`).
 */
/** 📖️The frozen outcome-code vocabulary's language-agnostic document — the one table this gate, the Rust protocol
 * (`OUTCOME_CODES`, persistence) and the TypeScript twin (`outcomeCodeLevel`) share. */
const POLICY_OUTCOME_CODE_FIXTURE = "🧰️framework/🔨️modules/📡️replication/🎮️mutation/🧫️fixtures/🧫️outcome-code/🔣️.json";
type PolicyOutcomeLevel = "info" | "warning" | "error" | "fatal";
export type PolicyOutcomeVocabulary = Readonly<{ codes: ReadonlyMap<string, PolicyOutcomeLevel>; applyPattern: RegExp; applyLevel: PolicyOutcomeLevel }>;

/** 📖️Reads the frozen vocabulary; a missing or malformed document fails the gate instead of admitting everything. */
export function policyOutcomeVocabulary(repoRoot: string): PolicyOutcomeVocabulary {
  const document = JSON.parse(policyReadFileSafe(repoRoot, POLICY_OUTCOME_CODE_FIXTURE)) as { codes: { code: string; level: PolicyOutcomeLevel }[]; apply: { pattern: string; level: PolicyOutcomeLevel } };
  return { codes: new Map(document.codes.map((row) => [row.code, row.level])), applyPattern: new RegExp(document.apply.pattern), applyLevel: document.apply.level };
}

/** ⚖️The level the vocabulary fixes for `code`; `null` outside it. */
function policyOutcomeCodeLevel(vocabulary: PolicyOutcomeVocabulary, code: string): PolicyOutcomeLevel | null {
  return vocabulary.codes.get(code) ?? (vocabulary.applyPattern.test(code) ? vocabulary.applyLevel : null);
}

/** 🗂️What the mutation-outcome-law rules read: git-visible regular source files and the `🧬️mutations` directories above them. */
type PolicyMutationLawInventory = Readonly<{ files: readonly string[]; mutationsDirs: readonly string[] }>;
/** 🔎️Every position the rules scan: sources, Python oracles, Gherkin specifications and committed `🎯️outcome` documents. */
const POLICY_MUTATION_LAW_PATHSPECS = ["*.rs", "*.ts", "*.tsx", "*.py", "*.feature", "*🎯️outcome/🔣️.json"] as const;
const POLICY_MUTATION_LAW_INVENTORIES = new Map<string, PolicyMutationLawInventory>();

/**
 * 🗂️The mutation-outcome-law gate's ONE repo walk, memoized per root and shared by every rule of this region: git's own inventory of
 * tracked and unignored files (`git ls-files -co --exclude-standard`), so ignored build trees are never entered and a
 * symlink is never followed — git lists a link as one path and nothing beneath it. Taxonomy `pathExclusions` (opaque
 * prefixes), `POLICY_SKIP_DIRS` segments and the router itself drop before any filesystem access, and `lstat` keeps regular
 * files only, so a link (the root `.tmp-ticket` convenience link) or a deleted tracked path is skipped instead of read.
 */
export function policyMutationLawInventory(repoRoot: string): PolicyMutationLawInventory {
  const cached = POLICY_MUTATION_LAW_INVENTORIES.get(repoRoot);
  if (cached) return cached;
  const listed = Bun.spawnSync(["git", "ls-files", "-co", "--exclude-standard", "-z", "--", ...POLICY_MUTATION_LAW_PATHSPECS], { cwd: repoRoot });
  if (listed.exitCode !== 0) throw new Error(`git-visible mutation-outcome-law inventory failed: ${listed.stderr.toString()}`);
  const taxonomy = loadTaxonomy();
  const files = [...new Set(listed.stdout.toString().split("\0").map((relPath) => relPath.normalize("NFC")))]
    .filter((relPath) => relPath && !POLICY_MUTATION_LAW_SELF_PATHS.has(relPath) && !relPath.split("/").some((segment) => POLICY_SKIP_DIRS.has(segment)) && !taxonomyRelativePathIsExcluded(relPath, taxonomy))
    .filter((relPath) => {
      try {
        return lstatSync(join(repoRoot, relPath)).isFile();
      } catch {
        return false;
      }
    })
    .sort();
  const mutationsDirs = new Set<string>();
  for (const relPath of files) {
    const segments = relPath.split("/");
    for (let index = 0; index < segments.length - 1; index++) if (segments[index] === POLICY_MUTATIONS_FACET) mutationsDirs.add(segments.slice(0, index + 1).join("/"));
  }
  const inventory: PolicyMutationLawInventory = { files, mutationsDirs: [...mutationsDirs].sort() };
  POLICY_MUTATION_LAW_INVENTORIES.set(repoRoot, inventory);
  return inventory;
}

/** 🦀️The inventory's Rust sources. */
function policyMutationLawRustFiles(repoRoot: string): string[] {
  return policyMutationLawInventory(repoRoot).files.filter((relPath) => relPath.endsWith(".rs"));
}

/** 🧩️ A direct mutation is composite exactly when it visibly owns an explicit plan facet. */
function policyIsCompositeMutationDir(repoRoot: string, mutationRel: string): boolean {
  return existsSync(join(repoRoot, mutationRel, POLICY_MUTATION_PLAN_DIR, POLICY_RS_COMPONENT_LEAF_NAME));
}

/** 🔎️`use protocol::MutationOutcome;` or `use protocol::{.., MutationOutcome, ..};` — the import that lets a leaf spell the contract bare. */
const POLICY_OUTCOME_IMPORT_RE = /\buse\s+protocol::(?:MutationOutcome\b|\{[^}]*\bMutationOutcome\b[^}]*\})/;

/** 🧾️Whether a `🔺️diff` leaf reports through the frozen contract: `protocol::MutationOutcome<..>` spelled qualified, or bare after importing it from `protocol`. */
function policyDiffReturnsOutcome(content: string): boolean {
  return /protocol::MutationOutcome\s*</.test(content) || (POLICY_OUTCOME_IMPORT_RE.test(content) && /->\s*MutationOutcome\s*</.test(content));
}

/**
 * 📏️Rule 1: every `🧬️mutations/<slug>/🔺️diff/🦀️.rs` must return `protocol::MutationOutcome<` (qualified, or bare after
 * `use protocol::MutationOutcome`) and reference at least one of the 9 frozen codes. Composite mutation dirs (own `🧩️plan`, not `🔺️diff`) are out of scope — their outcome folds from
 * the plan. A leaf whose `🔺️diff` doesn't exist yet is out of scope here: the rule judges only the diff leaves that exist.
 */
export function policyMutationOutcomeBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  const vocabulary = policyOutcomeVocabulary(repoRoot);
  for (const mutationsRel of policyMutationLawInventory(repoRoot).mutationsDirs) {
    const artRel = policyArtifactRootOfMutationsDir(mutationsRel);
    for (const mutName of policyListMutationDirs(repoRoot, mutationsRel)) {
      const mutRel = `${mutationsRel}/${mutName}`;
      if (policyIsCompositeMutationDir(repoRoot, mutRel)) continue;
      const diffRel = `${mutRel}/🔺️diff/${POLICY_RS_COMPONENT_LEAF_NAME}`;
      if (!existsSync(join(repoRoot, diffRel))) continue;
      const content = policyReadFileSafe(repoRoot, diffRel);
      if (!policyDiffReturnsOutcome(content)) {
        breaches.push({
          id: `mutation-outcome-missing-type-${diffRel}`,
          summary: `"${diffRel}" does not return protocol::MutationOutcome<..>`,
          kind: "mutation-migration/outcome",
          scope: artRel,
          priority: "high",
          reason: "C2/C4: every 🔺️diff leaf must report through the frozen MutationOutcome<D> contract.",
          solution: `Change diff's signature to -> protocol::MutationOutcome<XDiff> and wrap the success path in MutationOutcome::new(..) (see 📋️contract-freeze.md's fan-out recipe, or the already-converted 🕸️dag/📐️cad/💠️lowpoly facets).`,
        });
        continue;
      }
      const hasCode = [...vocabulary.codes.keys()].some((code) => content.includes(code) || content.includes(`OutcomeCode::${code.replace(/^mutation\./, "").replace(/(?:^|-)([a-z])/g, (_, letter: string) => letter.toUpperCase())}`));
      if (hasCode) continue;
      breaches.push({
        id: `mutation-outcome-missing-code-${diffRel}`,
        summary: `"${diffRel}" returns protocol::MutationOutcome<..> but never references one of the 9 frozen message codes`,
        kind: "mutation-migration/outcome",
        scope: artRel,
        priority: "high",
        reason: "The verb-family table requires real Error/Warning/Fatal/Info detection per verb family; no mutation architecture is exempt.",
        solution: `Add the real detection this verb family requires (target missing ⇒ ::error("mutation.target-missing", ..), idempotent ⇒ .warning("mutation.no-op", ..), duplicate id / invariant ⇒ ::fatal(..), cascade ⇒ .info("mutation.cascade", ..)).`,
      });
    }
  }
  return breaches;
}

/** 🔎️Rust outcome builders with the level they fix: `MutationOutcome::(error|fatal)(..)` and `MutationMessage::(info|warning|error|fatal)(..)`. */
const POLICY_OUTCOME_RUST_BUILDER_RE = /\b(?:MutationOutcome::(error|fatal)|MutationMessage::(info|warning|error|fatal))\s*\(\s*"([^"]*)"/g;
/** 🔎️The chainable `.info(..)`/`.warning(..)` shorthand — checked only inside a `fn` body that builds a `MutationOutcome`, so an unrelated sink's `.warning(..)`/`tracing::warn!` never matches. */
const POLICY_OUTCOME_RUST_CHAIN_RE = /\.(info|warning)\s*\(\s*"([^"]*)"/g;
/** 🔎️The retired `warn` builder spelling: `MutationMessage::warn(..)` anywhere, the chainable `.warn(..)` inside an outcome-building body. */
const POLICY_OUTCOME_RUST_RETIRED_BUILDER_RE = /(?:\bMutationMessage::|\.)warn\s*\(/g;
/** 🔎️Apply-time rejections (`MutationOutcome::apply_to` persists them as `Fatal` messages): `MutationApplyError::new("…")`, `MutationApplyError { code: "…" }`. */
const POLICY_OUTCOME_RUST_APPLY_RE = /\bMutationApplyError(?:::new\s*\(\s*|\s*\{\s*code:\s*)"([^"]*)"/g;
/** 🔎️TypeScript twins: `refuse("<level>", "<code>", ..)` and `{ level: "<level>", code: "mutation.…" }` messages (the retired `warn` spelling is matched so it is reported, never skipped). */
const POLICY_OUTCOME_TS_REFUSE_RE = /\brefuse\(\s*"(info|warn|warning|error|fatal)"\s*,\s*"([^"]*)"/g;
const POLICY_OUTCOME_TS_OBJECT_RE = /\blevel:\s*"(info|warn|warning|error|fatal)"\s*,\s*code:\s*"(mutation\.[^"]*)"|\bcode:\s*"(mutation\.[^"]*)"\s*,\s*level:\s*"(info|warn|warning|error|fatal)"/g;
/** 🔎️Python second implementations: `("<level>", "<dotted-code>")` outcome tuples. */
const POLICY_OUTCOME_PY_TUPLE_RE = /\(\s*"(info|warn|warning|error|fatal)"\s*,\s*"([a-z0-9]+(?:[.-][a-z0-9]+)+)"\s*\)/g;
/** 🔎️Gherkin outcome messages: `{level: <level>, code: mutation.…}`. */
const POLICY_OUTCOME_FEATURE_MESSAGE_RE = /\blevel:\s*([a-z]+)\s*,\s*code:\s*(mutation\.[a-z0-9][a-z0-9.-]*[a-z0-9])(?![\w.<*-])/g;
/** 🔎️A hand-written Rust level decoder admitting the retired `"warn"` spelling for `Severity::Warning` — the wire name is `warning` only. */
const POLICY_OUTCOME_RUST_LEVEL_ALIAS_RE = /(?:"[a-z]+"\s*\|\s*)*"warn"\s*(?:\|\s*"[a-z]+"\s*)*=>\s*(?:Ok\(|Some\()?(?:[A-Za-z_]\w*::)*Severity::Warning\b/g;
/** 🔎️A complete string literal in the `mutation.` namespace — an outcome code wherever mutation leaves, diffs and oracles spell one. */
const POLICY_OUTCOME_NAMESPACE_LITERAL_RE = /["'`](mutation\.[a-z0-9][a-z0-9.-]*)["'`]/g;
/** 🔎️A `mutation.` token in a Gherkin specification (`mutation.apply.<detail>` placeholders excluded). */
const POLICY_OUTCOME_FEATURE_TOKEN_RE = /(?<![\w.-])(mutation\.[a-z0-9][a-z0-9-]*(?:\.[a-z0-9][a-z0-9-]*)*)(?![\w-]|\.[<*])/g;
/** 🔎️Finds `fn <name>(..` openers so the chainable shorthand is scoped to outcome-building bodies. */
const POLICY_FN_DECL_RE = /\bfn\s+[A-Za-z_]\w*/g;
/** 🔎️Outcome-code positions by domain: mutation leaves, diffs and their oracles. */
const POLICY_OUTCOME_LEAF_SEGMENTS = ["/🧬️mutations/", "/🔺️diff/"] as const;

/** 🧱️Spans of every `fn` body that mentions `MutationOutcome`, found with ONE literal-masked brace pass per file. */
function policyOutcomeFnBodyMask(content: string): Uint8Array {
  const masked = policyMaskLiterals(content);
  const close = new Int32Array(masked.length).fill(-1);
  const stack: number[] = [];
  for (let i = 0; i < masked.length; i++) {
    const ch = masked.charCodeAt(i);
    if (ch === 123) stack.push(i);
    else if (ch === 125) {
      const open = stack.pop();
      if (open !== undefined) close[open] = i;
    }
  }
  const mask = new Uint8Array(content.length);
  POLICY_FN_DECL_RE.lastIndex = 0;
  let fm: RegExpExecArray | null;
  while ((fm = POLICY_FN_DECL_RE.exec(masked))) {
    const open = masked.indexOf("{", fm.index);
    const end = open === -1 ? -1 : close[open]!;
    if (end !== -1 && content.slice(open, end + 1).includes("MutationOutcome")) mask.fill(1, open, end + 1);
  }
  return mask;
}

/**
 * 📏️Rule 2: every outcome-code position spells a code of the frozen vocabulary (`🎮️mutation/🧫️fixtures/🧫️outcome-code`)
 * at the one level it fixes — persistence (`🏪️store` `expected_mutation_message_level`) refuses anything else. Positions:
 * Rust builders and the chainable shorthand inside outcome-building bodies (code + level), `MutationApplyError` codes
 * (`mutation.apply.<detail>`), `mutation.` literals in mutation leaves/diffs (Rust, TypeScript) and Python oracles, the
 * TypeScript twins' `refuse(..)`/`{ level, code }` messages, Python `(level, code)` tuples, committed `🎯️outcome` documents
 * (code + level), Gherkin specifications (codes and `{level, code}` messages) and hand-written Rust level decoders. A level
 * has one spelling (`warning`, never `warn`). Non-outcome fault, diagnostic and command codes live in their own namespaces.
 */
export function policyMutationMessageCodeBreaches(repoRoot: string): BreachRecord[] {
  const vocabulary = policyOutcomeVocabulary(repoRoot);
  return policyMutationLawInventory(repoRoot).files.flatMap((relPath) => policyOutcomeCodeFileBreaches(vocabulary, relPath, policyReadFileSafe(repoRoot, relPath)));
}

/**
 * 🔬️Rule 2 over ONE file, pure: the outcome-code positions of `content` (classified by `relPath`'s extension and domain
 * segments) checked against `vocabulary`. A scanned level is whatever the source spells (`warn` included), so a retired or
 * foreign spelling is reported instead of being cast into the vocabulary's level type. The planted-violation law
 * (`🧪️tests/🧪️outcome-law-gate`) drives exactly this function.
 */
export function policyOutcomeCodeFileBreaches(vocabulary: PolicyOutcomeVocabulary, relPath: string, content: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  if (!content || (relPath.endsWith(".py") && !relPath.includes("🧪️tests/"))) return breaches;
  const reported = new Set<string>();
  const check = (code: string, level: string | null, index: number, apply = false) => {
    const expected = policyOutcomeCodeLevel(vocabulary, code);
    const fault = apply ? (vocabulary.applyPattern.test(code) ? null : "is not a mutation.apply.<detail> apply-rejection code") : expected === null ? "is not in the frozen outcome vocabulary" : level !== null && level !== expected ? `is fixed at ${expected}, not ${level}` : null;
    if (fault === null) return;
    const line = policyLineOfIndex(content, index);
    if (reported.has(`${line}:${code}`)) return;
    reported.add(`${line}:${code}`);
    breaches.push({
      id: `mutation-message-code-${relPath}-${line}-${code}`,
      summary: `"${relPath}:${line}" outcome code "${code}"${level === null ? "" : ` at ${level}`} ${fault}`,
      kind: "mutation-migration/message-code",
      scope: relPath,
      line,
      priority: "high",
      reason: "Persistence admits exactly the frozen outcome vocabulary, each code at its one level (`🎮️mutation/🧫️fixtures/🧫️outcome-code`); any other code or level makes the history unpersistable. There are no per-plugin codes.",
      solution: "Map the refusal by meaning: missing → mutation.target-missing, still referenced → mutation.target-referenced, inconsistent with the current state → mutation.target-mismatch, duplicate identity → mutation.duplicate-id, payload-intrinsic → mutation.invariant (+ schema bound or x-semio-invariant), apply-time failure → mutation.apply.<detail>; use the level the vocabulary fixes (MutationOutcome::refuse picks it for runtime codes).",
    });
  };
  const scan = (re: RegExp, visit: (m: RegExpExecArray) => void) => {
    re.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = re.exec(content))) visit(m);
  };
  const leaf = POLICY_OUTCOME_LEAF_SEGMENTS.some((segment) => `/${relPath}`.includes(segment));
  if (relPath.endsWith(".rs")) {
    scan(POLICY_OUTCOME_RUST_BUILDER_RE, (m) => check(m[3]!, (m[1] ?? m[2])!, m.index));
    scan(POLICY_OUTCOME_RUST_APPLY_RE, (m) => check(m[1]!, null, m.index, true));
    if (leaf) scan(POLICY_OUTCOME_NAMESPACE_LITERAL_RE, (m) => check(m[1]!, null, m.index));
    const bodies = content.includes("MutationOutcome") ? policyOutcomeFnBodyMask(content) : new Uint8Array(content.length);
    scan(POLICY_OUTCOME_RUST_CHAIN_RE, (m) => {
      if (bodies[m.index] === 1) check(m[2]!, m[1]!, m.index);
    });
    scan(POLICY_OUTCOME_RUST_RETIRED_BUILDER_RE, (m) => {
      if (m[0].startsWith(".") && bodies[m.index] !== 1) return;
      const line = policyLineOfIndex(content, m.index);
      breaches.push({
        id: `mutation-message-retired-builder-${relPath}-${line}-${m.index}`,
        summary: `"${relPath}:${line}" outcome builder "warn" is a retired spelling of "warning"`,
        kind: "mutation-migration/message-code",
        scope: relPath,
        line,
        priority: "high",
        reason: "An outcome level has one spelling in the API as on the wire: `MutationMessage::warning` / `MutationOutcome::warning` build the `warning` level.",
        solution: "Call `MutationMessage::warning(..)` / `.warning(..)`.",
      });
    });
    scan(POLICY_OUTCOME_RUST_LEVEL_ALIAS_RE, (m) => {
      const line = policyLineOfIndex(content, m.index);
      breaches.push({
        id: `mutation-message-level-alias-${relPath}-${line}`,
        summary: `"${relPath}:${line}" outcome level "warn" is a retired spelling of "warning"`,
        kind: "mutation-migration/message-code",
        scope: relPath,
        line,
        priority: "high",
        reason: "An outcome level has one wire spelling (`info`, `warning`, `error`, `fatal` — `Severity`'s own encoding); a decoder that also admits `warn` lets a non-canonical document pass as valid.",
        solution: 'Decode only "warning" (or use the `Severity` value decoder) and write "warning" in every committed outcome.',
      });
    });
  } else if (relPath.endsWith(".ts") || relPath.endsWith(".tsx")) {
    scan(POLICY_OUTCOME_TS_REFUSE_RE, (m) => check(m[2]!, m[1]!, m.index));
    scan(POLICY_OUTCOME_TS_OBJECT_RE, (m) => check((m[2] ?? m[3])!, (m[1] ?? m[4])!, m.index));
    if (leaf) scan(POLICY_OUTCOME_NAMESPACE_LITERAL_RE, (m) => check(m[1]!, null, m.index));
  } else if (relPath.endsWith(".py")) {
    scan(POLICY_OUTCOME_PY_TUPLE_RE, (m) => check(m[2]!, m[1]!, m.index));
    scan(POLICY_OUTCOME_NAMESPACE_LITERAL_RE, (m) => check(m[1]!, null, m.index));
  } else if (relPath.endsWith(".feature")) {
    scan(POLICY_OUTCOME_FEATURE_TOKEN_RE, (m) => {
      if (!/\.(json|rs|ts|tsx|py|md|txt)$/.test(m[1]!)) check(m[1]!, null, m.index);
    });
    scan(POLICY_OUTCOME_FEATURE_MESSAGE_RE, (m) => check(m[2]!, m[1]!, m.index));
  } else {
    let outcome: unknown;
    try {
      outcome = JSON.parse(content);
    } catch {
      return breaches;
    }
    if (outcome === null || typeof outcome !== "object") return breaches;
    const level = (value: unknown): string | null => (typeof value === "string" ? value : null);
    const record = outcome as { code?: unknown; level?: unknown; messages?: unknown };
    let cursor = 0;
    const locate = (code: string): number => {
      const at = content.indexOf(JSON.stringify(code), cursor);
      cursor = at === -1 ? cursor : at + 1;
      return at === -1 ? 0 : at;
    };
    for (const message of [record, ...(Array.isArray(record.messages) ? (record.messages as { code?: unknown; level?: unknown }[]) : [])]) {
      if (message !== null && typeof message === "object" && typeof message.code === "string") check(message.code, level(message.level), locate(message.code));
    }
  }
  return breaches;
}

/** 🔎️CRDT-era vocabulary C10 deletes: `merge_strategy`, `MergeStrategyKind`, `merge_concurrent_diffs`, `ConflictRule`, `ResolutionPlan`, `assert_crdt_*`. */
const POLICY_CRDT_VOCABULARY_TOKENS = ["merge_strategy", "MergeStrategyKind", "merge_concurrent_diffs", "ConflictRule", "ResolutionPlan", "assert_crdt_"] as const;
const POLICY_CRDT_VOCABULARY_RE = new RegExp(`\\b(${POLICY_CRDT_VOCABULARY_TOKENS.join("|")})`, "g");

/**
 * 📏️Rule 3: zero repo-wide occurrences of the CRDT merge-strategy/conflict-rule vocabulary C10 deletes
 * (git-visible files of `policyMutationLawInventory`; `.🧬semio/`, `node_modules`, `target`, `dist` excluded via `POLICY_SKIP_DIRS`). Scoped to `.rs` files —
 * every token is a Rust-only identifier (no TS mirror was ever specified for the deleted CRDT pair).
 */
export function policyNoCrdtVocabularyBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const relPath of policyMutationLawRustFiles(repoRoot)) {
    const content = policyReadFileSafe(repoRoot, relPath);
    if (!content) continue;
    POLICY_CRDT_VOCABULARY_RE.lastIndex = 0;
    const seenLines = new Set<number>();
    let m: RegExpExecArray | null;
    while ((m = POLICY_CRDT_VOCABULARY_RE.exec(content))) {
      const line = policyLineOfIndex(content, m.index);
      if (seenLines.has(line)) continue;
      seenLines.add(line);
      breaches.push({
        id: `no-crdt-vocabulary-${relPath}-${line}`,
        summary: `"${relPath}:${line}" still references CRDT vocabulary "${m[1]}"`,
        kind: "mutation-migration/no-crdt-vocabulary",
        scope: relPath,
        line,
        priority: "high",
        reason: "C10 deletes 📡️spr/🔀️crdt/** and its whole vocabulary in favor of C3's MergePolicy + C5's first-class Conflict — merge_strategy/MergeStrategyKind/merge_concurrent_diffs/ConflictRule/ResolutionPlan/assert_crdt_* must reach zero occurrences repo-wide.",
        solution: `Delete or rewrite this reference — reach for protocol::MergePolicy / the new 📡️spr/⚔️conflict module instead (📋️contract-freeze.md §C3/C5/C10).`,
      });
    }
  }
  return breaches;
}

/** 🔎️A `fn validate(&self, ..)` override — the exact shape C4/C10 delete from `Mutation`/`MutationKind`/`CompositeMutationKind`. */
const POLICY_VALIDATE_OVERRIDE_RE = /\bfn\s+validate\s*\(\s*&self\b/g;
/** 🔎️An `impl (protocol::)?(Composite)?MutationKind<..> for X {` block opener, to scope the second half of rule 4. */
const POLICY_MUTATION_KIND_IMPL_RE = /\bimpl\b[^\n{]*\b(?:CompositeMutationKind|MutationKind)\s*</g;

/**
 * 📏️Rule 4: no `fn validate(&self, ..)` survives — not inside a `🧬️mutations/**` file, and not inside
 * any `impl … MutationKind`/`impl … CompositeMutationKind` block anywhere (hand-written config/presence
 * enums included). Its checks move into the `🔺️diff` leaf as Error/Fatal messages (C4/C10). Note: gltf's
 * `pub fn validate(payload: &P, base: &S) -> Result<(), GltfTopLevelMutationRejection>` is a FREE function
 * with no `&self` receiver — a structurally different shape that this rule never matches.
 */
export function policyNoValidateOverrideBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const relPath of policyMutationLawRustFiles(repoRoot)) {
    const content = policyReadFileSafe(repoRoot, relPath);
    if (!content) continue;
    const reportedLines = new Set<number>();
    const pushBreach = (line: number, detail: string) => {
      if (reportedLines.has(line)) return;
      reportedLines.add(line);
      breaches.push({
        id: `no-validate-override-${relPath}-${line}`,
        summary: `"${relPath}:${line}" still overrides fn validate(&self, ..) ${detail}`,
        kind: "mutation-migration/no-validate-override",
        scope: relPath,
        line,
        priority: "high",
        reason: "C4/C10: validate no longer exists on Mutation/MutationKind/CompositeMutationKind — every override is deleted, its checks moved into the 🔺️diff leaf as Error/Fatal messages.",
        solution: `Delete this fn validate override; move its check into the sibling 🔺️diff leaf as a protocol::MutationOutcome::error(..)/::fatal(..) message.`,
      });
    };

    const underMutations = relPath.replaceAll("\\", "/").includes(`/${POLICY_MUTATIONS_FACET}/`);
    if (underMutations) {
      POLICY_VALIDATE_OVERRIDE_RE.lastIndex = 0;
      let vm: RegExpExecArray | null;
      while ((vm = POLICY_VALIDATE_OVERRIDE_RE.exec(content))) pushBreach(policyLineOfIndex(content, vm.index), `under a 🧬️mutations/ leaf`);
    }

    POLICY_MUTATION_KIND_IMPL_RE.lastIndex = 0;
    let im: RegExpExecArray | null;
    while ((im = POLICY_MUTATION_KIND_IMPL_RE.exec(content))) {
      const body = policyExtractFnBody(content, im.index);
      POLICY_VALIDATE_OVERRIDE_RE.lastIndex = 0;
      const vm = POLICY_VALIDATE_OVERRIDE_RE.exec(body);
      if (!vm) continue;
      pushBreach(policyLineOfIndex(content, im.index + vm.index), `inside an impl …MutationKind block`);
    }
  }
  return breaches;
}

/** 🔎️The canonical root command router excludes only its own source from the policy scan. */
const POLICY_MUTATION_LAW_SELF_PATHS = new Set<string>(["📜️script.ts"]);

/** 🔎️The inventory's source files (`.rs`/`.ts`/`.tsx`) repo-wide — the canonical root router, whose policy literals must not scan themselves, is already out. */
function policyMutationLawSourceFiles(repoRoot: string): string[] {
  return policyMutationLawInventory(repoRoot).files.filter((relPath) => relPath.endsWith(".rs") || relPath.endsWith(".ts") || relPath.endsWith(".tsx"));
}

const POLICY_SEVERITY_HINT_STRUCT_RE = /\bSeverity(?:::|\.)Hint\b/g;

/**
 * 📏️Rule 5: zero `Severity::Hint`/`Severity.Hint` (C1 declaration order is now `Info, Warning, Error,
 * Fatal` — `derive(Ord)` IS the level order, Hint was folded into Info repo-wide), and zero bare `"hint"`
 * severity-literal on a line that also mentions "severity"/"level" (scoped to avoid flagging the ordinary
 * English word "hint" used for unrelated UI copy/tooltips).
 */
export function policySeverityInfoBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const relPath of policyMutationLawSourceFiles(repoRoot)) {
    const content = policyReadFileSafe(repoRoot, relPath);
    if (!content) continue;
    const reportedLines = new Set<number>();
    POLICY_SEVERITY_HINT_STRUCT_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = POLICY_SEVERITY_HINT_STRUCT_RE.exec(content))) {
      const line = policyLineOfIndex(content, m.index);
      if (reportedLines.has(line)) continue;
      reportedLines.add(line);
      breaches.push({
        id: `severity-hint-${relPath}-${line}`,
        summary: `"${relPath}:${line}" still references Severity::Hint/Severity.Hint`,
        kind: "mutation-migration/no-severity-hint",
        scope: relPath,
        line,
        priority: "high",
        reason: "C1 collapsed Hint into Info repo-wide; Severity's declaration order (Info < Warning < Error < Fatal, 0..3) has no Hint member anymore.",
        solution: `Rewrite this to Severity::Info / "Info" — Hint was merged into Info by C1.`,
      });
    }
    const lines = content.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      if (!/["']hint["']/i.test(line) || !/severity|level/i.test(line)) continue;
      const lineNo = i + 1;
      if (reportedLines.has(lineNo)) continue;
      reportedLines.add(lineNo);
      breaches.push({
        id: `severity-hint-literal-${relPath}-${lineNo}`,
        summary: `"${relPath}:${lineNo}" uses a "hint" severity literal`,
        kind: "mutation-migration/no-severity-hint",
        scope: relPath,
        line: lineNo,
        priority: "high",
        reason: "C1 collapsed Hint into Info repo-wide; a serialized/matched severity level literal must never be \"hint\".",
        solution: `Rewrite the literal to "info" — Hint was merged into Info by C1.`,
      });
    }
  }
  return breaches;
}

/** 🔎️The 3 frozen MergePolicy variants (C3) spelled at exactly these 4 surfaces. */
const POLICY_MERGE_POLICY_VARIANTS = ["LaissezFaire", "Normal", "Vigilant"] as const;
/** 🔡️Idiomatic per-language spelling accepted for each variant — Rust surfaces spell it exactly like the enum (`LaissezFaire`); TS surfaces (kernel types, label contract, i18n bundles) may use either the PascalCase mirror or the camelCase object-key form (`laissezFaire`) that idiomatic TS reaches for. Presence-only, per surface's own convention — this is a mirror-existence check, not a shape check. */
const POLICY_MERGE_POLICY_VARIANT_SPELLINGS: Readonly<Record<(typeof POLICY_MERGE_POLICY_VARIANTS)[number], readonly string[]>> = {
  LaissezFaire: ["LaissezFaire", "laissezFaire"],
  Normal: ["Normal", "normal"],
  Vigilant: ["Vigilant", "vigilant"],
};
/** 🗺️The surfaces that SPELL the variants. The host codec (`💻️os/🟦️.ts`) carries only the ordinal through the kernel twin's `mergePolicyAsU8`, so the kernel types stand for it. */
const POLICY_MERGE_POLICY_SURFACES: readonly { label: string; relPath: string }[] = [
  { label: "Rust spine (protocol::MergePolicy, 📡️replication/🧾️wire)", relPath: "🧰️framework/🔨️modules/📡️replication/🧾️wire/🦀️.rs" },
  { label: "TS kernel types (🎠️kernel/🟦️.ts)", relPath: "🧰️framework/🔨️modules/🎠️kernel/🟦️.ts" },
  { label: "UI label contract (📚️I18n policy.*)", relPath: "🧰️framework/🔨️modules/🖱️ui/🧱️elements/📚️I18n/🟦️.tsx" },
  { label: "i18n bundles (en+de, ⚛️react/🌐️i18n)", relPath: "🧰️framework/🔨️modules/🖱️ui/🎯️targets/⚛️react/🌐️i18n/🟦️.ts" },
];

/**
 * 📏️Rule 6: the three `MergePolicy` variants must be present in all 4 surfaces that spell them (C3/C9),
 * each under whatever idiomatic spelling that surface's language uses (`POLICY_MERGE_POLICY_VARIANT_
 * SPELLINGS` — as substrings, this is a mirror-existence check, not a shape check); one breach per surface
 * that is missing at least one variant under any of its spellings, or that no longer exists at all.
 */
export function policyMergePolicyParityBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const surface of POLICY_MERGE_POLICY_SURFACES) {
    const content = policyReadFileSafe(repoRoot, surface.relPath);
    const missing = content ? POLICY_MERGE_POLICY_VARIANTS.filter((v) => !POLICY_MERGE_POLICY_VARIANT_SPELLINGS[v].some((spelling) => content.includes(spelling))) : [...POLICY_MERGE_POLICY_VARIANTS];
    if (missing.length === 0) continue;
    breaches.push({
      id: `merge-policy-parity-${surface.relPath}`,
      summary: content ? `"${surface.relPath}" (${surface.label}) is missing MergePolicy variant(s): ${missing.join(", ")}` : `"${surface.relPath}" (${surface.label}) does not exist — the surface moved and this gate lists a stale path`,
      kind: "mutation-migration/merge-policy-parity",
      scope: surface.relPath,
      priority: "high",
      reason: "C3/C9: MergePolicy {LaissezFaire, Normal, Vigilant} must mirror across all 4 surfaces that spell it (Rust spine, TS kernel types, UI label contract, en+de i18n bundles) or the merge-policy setting silently desyncs across a surface.",
      solution: content ? `Add the missing MergePolicy variant name(s) to ${surface.relPath} (see 📋️contract-freeze.md §C3/C9 for the exact shape expected at this surface).` : `Point POLICY_MERGE_POLICY_SURFACES at the file that now spells this surface.`,
    });
  }
  return breaches;
}

const POLICY_DERIVE_OWNER = "🧰️framework/🛍️products/💻️os/🔨️modules/🗣️dsl/✨️derive/🦀️.rs";
const POLICY_DERIVE_GLUE = "🧰️framework/🛍️products/💻️os/🔨️modules/🗣️dsl/✨️derive/📦️packages/🦀️rust/🦀️.rs";
/** 🔎️The glue's one mount of the owner implementation. */
const POLICY_DERIVE_GLUE_MOUNT_RE = /#\[path\s*=\s*"\.\.\/\.\.\/🦀️\.rs"\]\s*mod\s+component\s*;/;

/** 📏️Rule 7: the dsl derive macro has ONE implementation — the proc-macro package glue mounts the owner `🦀️.rs` (`#[path = "../../🦀️.rs"] mod component;`) and only forwards to it, so no build shape can run a stale copy of the derive logic. */
export function policyDeriveGlueMountBreaches(repoRoot: string): BreachRecord[] {
  const glue = policyReadFileSafe(repoRoot, POLICY_DERIVE_GLUE);
  if (policyReadFileSafe(repoRoot, POLICY_DERIVE_OWNER) && POLICY_DERIVE_GLUE_MOUNT_RE.test(glue) && !/\bfn\s+expand_/.test(glue)) return [];
  return [
    {
      id: `derive-glue-mount-${POLICY_DERIVE_GLUE}`,
      summary: `"${POLICY_DERIVE_GLUE}" does not mount the derive owner "${POLICY_DERIVE_OWNER}" as its one implementation`,
      kind: "mutation-migration/derive-glue-mount",
      scope: POLICY_DERIVE_GLUE,
      priority: "high",
      reason: "The dsl derive macro's proc-macro package is glue: it mounts the owner implementation instead of carrying a copy, so the macro body exists once and no build shape runs stale derive logic.",
      solution: `Make ${POLICY_DERIVE_GLUE} mount the owner with #[path = "../../🦀️.rs"] mod component; and forward each #[proc_macro_derive] entry to component::expand_*; move any expand_* body into ${POLICY_DERIVE_OWNER}.`,
    },
  ];
}

type PolicyDiffOnlyRuleId = "R8" | "R9" | "R10" | "R11" | "R12" | "R13" | "R14" | "R15" | "R16";
type PolicyDiffOnlyRule = Readonly<{ code: string; slug: string; reason: string; solution: string }>;

/** 📜️The diff-only mutation law's rules (`26/10/08/DIFF-ONLY-MUTATIONS-WITH-CENTRAL-APPLY-AND-DIFF-SUMMING-INVERSES` design L1–L5, violation codes V1–V4): one reason and one remedy per rule, keyed by rule id. */
const POLICY_DIFF_ONLY_RULES: Readonly<Record<PolicyDiffOnlyRuleId, PolicyDiffOnlyRule>> = {
  R8: { code: "V3-LEAF-APPLY", slug: "leaf-mutable-base", reason: "a mutation leaf's diff/inverse takes or creates a `&mut`", solution: "Build the sparse diff or concrete inverse declaratively from the payload and reads of `base`; only the central applier writes into a snapshot." },
  R9: { code: "V3-LEAF-APPLY", slug: "leaf-applies-diff", reason: "a mutation leaf applies a diff itself", solution: "Remove the apply: leaves never turn a diff into a snapshot; callers use `protocol::apply_diff`, which alone mints the `ApplyCapability`." },
  R10: { code: "V1-SNAPSHOT-DIFF", slug: "leaf-between", reason: "a mutation leaf builds its diff by differencing two snapshots", solution: "Name the changed entities and fields with their new values instead; `between` is for sync and import only." },
  R11: { code: "V2-DIFF-DERIVED-INVERSE", slug: "diff-derived-inverse", reason: "an inverse is derived from the forward diff", solution: "Build the inverse mutations from the payload and reads of `base` inside the leaf's own inverse, as absolute setters of the base values." },
  R12: { code: "V1-SNAPSHOT-DIFF", slug: "base-clone-diff", reason: "a diff body clones `base` into a mutable binding", solution: "Read `base` and emit the sparse diff rows directly; never edit a copy of the snapshot and difference it." },
  R13: { code: "V1-SNAPSHOT-DIFF", slug: "whole-state-diff", reason: "the diff type is the whole snapshot it applies to", solution: "Replace it with a sparse typed diff (keyed added/removed/modified rows) with a concrete `DiffAlgebra::inverse`." },
  R14: { code: "V2-RESTORE-INVERSE", slug: "restore-inverse", reason: "an inverse returns a whole-snapshot restore variant", solution: "Return the concrete mutations that put each touched value back to its exact base value." },
  R15: { code: "V4-LAW-UNTESTED", slug: "inverse-sum-law-untested", reason: "no test under the leaf's own `🧪️tests` calls `assert_mutation_inverse_sum_law`", solution: "Add a test under the leaf's `🧪️tests` that calls `assert_mutation_inverse_sum_law(&mutation, &before)` on each applied fixture." },
  R16: { code: "V3-LEAF-APPLY", slug: "outcome-apply-to", reason: "`MutationOutcome::apply_to` is gone: a diff is applied only by the central applier", solution: "Call `protocol::apply_diff(outcome.diff(), &base)` instead." },
};

/** 🧪️Directories whose Rust files are the leaf's own diff, inverse or mutation builders, where applying a diff is never allowed. */
const POLICY_DIFF_ONLY_APPLY_DIRS: ReadonlySet<string> = new Set(["🔺️diff", "↩️inverse", "🦠️mutation"]);
/** 🫧️Ephemeral lane directories (design ruling "Ephemeral roots"): presence and window transient travel by whole-root transfer, so they may keep ONE whole-root setter kind with a sparse diff and the same setter carrying the base root as its inverse; R13 and R14 exempt only files under these two directories, never persisted config or document lanes. */
const POLICY_DIFF_ONLY_EPHEMERAL_LANES: ReadonlySet<string> = new Set(["👥️presence", "🫧️transient"]);
/** 🔎️Raw cue that a file may hold a hand-written `impl … MutationKind<` or `impl … Mutation<` block. */
const POLICY_DIFF_ONLY_IMPL_PROBE_RE = /\bimpl\b[^{;]*\bMutation(?:Kind)?\s*</;
/** 🔎️Raw cue that a file may hold an `impl … MutationDiff<` block. */
const POLICY_DIFF_ONLY_DIFF_IMPL_PROBE_RE = /\bimpl\b[^{;]*\bMutationDiff\s*</;
const POLICY_RUST_RAW_STRING_RE = /b?r(#*)"/y;
const POLICY_RUST_TEST_ITEM_RE = /#\[\s*(?:cfg\s*\(\s*test\s*\)|test)\s*\]/g;
const POLICY_RUST_FN_RE = /\bfn\s+([A-Za-z_]\w*)/g;
const POLICY_RUST_IMPL_RE = /\bimpl\b/g;
const POLICY_RUST_USE_RE = /\buse\s[^;]*;/g;
const POLICY_DIFF_ONLY_APPLY_RE = /(?:\.|::)apply\s*\(|(?<!\bfn\s+)\bapply_diff\s*\(|\bApplyCapability\b/g;
const POLICY_DIFF_ONLY_BETWEEN_RE = /(?<!\bfn\s+)(?<!\w)between\s*\(/g;
const POLICY_DIFF_ONLY_MUT_REF_RE = /&\s*mut\b/g;
const POLICY_DIFF_ONLY_DIFF_CALL_RE = /(?<!\w)diff\s*\(/g;
const POLICY_DIFF_ONLY_INVERSE_HELPER_RE = /(?<![\w.])(\w*_inverse|\w*inverse_\w*)\s*\(/g;
const POLICY_DIFF_ONLY_DIFF_ARGUMENT_RE = /\b\w*[dD]iff\w*\b|\boutcome\b/;
const POLICY_DIFF_ONLY_RESTORE_RE = /\b(?:SetSnapshot|PatchSnapshot|ReplaceDocument|ReplaceSnapshot|Restore\w*)\b|\b(?:Self|[A-Z]\w*)::Snapshot\b/g;
const POLICY_DIFF_ONLY_APPLY_TO_RE = /(?:\.|::)apply_to\s*\(/g;
const POLICY_DIFF_ONLY_TYPE_DIFF_RE = /\btype\s+Diff\s*=\s*([^;]+);/;

/** 🩻️`content` with comments, string literals, raw strings and char literals blanked to spaces — same length, newlines kept — so every index and line number still addresses the original source. */
function policyMaskRustSource(content: string): string {
  const size = content.length;
  const pieces: string[] = [];
  let kept = 0;
  let index = 0;
  const blank = (from: number, to: number) => {
    pieces.push(content.slice(kept, from), content.slice(from, to).replace(/[^\n]/g, " "));
    kept = to;
    index = to;
  };
  while (index < size) {
    const ch = content[index]!;
    const next = content[index + 1];
    if (ch === "/" && next === "/") {
      const eol = content.indexOf("\n", index);
      blank(index, eol === -1 ? size : eol);
    } else if (ch === "/" && next === "*") {
      let depth = 1;
      let cursor = index + 2;
      while (cursor < size && depth > 0) {
        const pair = content.slice(cursor, cursor + 2);
        if (pair === "/*") {
          depth++;
          cursor += 2;
        } else if (pair === "*/") {
          depth--;
          cursor += 2;
        } else cursor++;
      }
      blank(index, cursor);
    } else if (ch === '"') {
      let cursor = index + 1;
      while (cursor < size && content[cursor] !== '"') cursor += content[cursor] === "\\" ? 2 : 1;
      blank(index, Math.min(cursor + 1, size));
    } else if ((ch === "r" || ch === "b") && !/\w/.test(content[index - 1] ?? " ")) {
      POLICY_RUST_RAW_STRING_RE.lastIndex = index;
      const raw = POLICY_RUST_RAW_STRING_RE.exec(content);
      if (raw) {
        const terminator = `"${raw[1]}`;
        const end = content.indexOf(terminator, index + raw[0].length);
        blank(index, end === -1 ? size : end + terminator.length);
      } else index++;
    } else if (ch === "'") {
      if (next === "\\") {
        const end = content.indexOf("'", index + 3);
        blank(index, end === -1 ? index + 1 : end + 1);
      } else {
        const width = (content.codePointAt(index + 1) ?? 0) > 0xffff ? 2 : 1;
        if (content[index + 1 + width] === "'") blank(index, index + 2 + width);
        else index++;
      }
    } else index++;
  }
  return pieces.join("") + content.slice(kept);
}

/** 🪢️For every `{` of `masked` the index of its matching `}` (`-1` when unmatched); braces inside masked comments and literals never count. */
function policyRustBraceClose(masked: string): Int32Array {
  const close = new Int32Array(masked.length).fill(-1);
  const stack: number[] = [];
  for (let index = 0; index < masked.length; index++) {
    const ch = masked.charCodeAt(index);
    if (ch === 123) stack.push(index);
    else if (ch === 125) {
      const open = stack.pop();
      if (open !== undefined) close[open] = index;
    }
  }
  return close;
}

/** 🧽️`masked` with every `#[cfg(test)]`/`#[test]` item blanked: unit-test modules and test functions are not mutation leaves. */
function policyRustBlankTestItems(masked: string, close: Int32Array): string {
  const pieces: string[] = [];
  let kept = 0;
  for (const match of masked.matchAll(POLICY_RUST_TEST_ITEM_RE)) {
    if (match.index < kept) continue;
    let cursor = match.index + match[0].length;
    while (cursor < masked.length && masked[cursor] !== "{" && masked[cursor] !== ";") cursor++;
    const end = masked[cursor] === "{" && close[cursor]! >= 0 ? close[cursor]! + 1 : Math.min(cursor + 1, masked.length);
    pieces.push(masked.slice(kept, match.index), masked.slice(match.index, end).replace(/[^\n]/g, " "));
    kept = end;
  }
  return pieces.join("") + masked.slice(kept);
}

/** ➰️The index just past the `>` closing the `<` at `open` (a `->` arrow never closes). */
function policyRustSkipAngles(text: string, open: number): number {
  let depth = 0;
  for (let index = open; index < text.length; index++) {
    const ch = text[index];
    if (ch === "<") depth++;
    else if (ch === ">" && text[index - 1] !== "-" && --depth === 0) return index + 1;
  }
  return text.length;
}

/** 🔗️The index of the `)` matching the `(` at `open`. */
function policyRustParenEnd(text: string, open: number): number {
  let depth = 0;
  for (let index = open; index < text.length; index++) {
    if (text[index] === "(") depth++;
    else if (text[index] === ")" && --depth === 0) return index;
  }
  return text.length;
}

/** ✂️Splits `text` at its top-level commas (angle, paren, bracket and brace depth zero). */
function policyRustSplitTop(text: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let from = 0;
  for (let index = 0; index < text.length; index++) {
    const ch = text[index]!;
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth++;
    else if (ch === ")" || ch === "]" || ch === "}" || (ch === ">" && text[index - 1] !== "-")) depth--;
    else if (ch === "," && depth === 0) {
      parts.push(text.slice(from, index));
      from = index + 1;
    }
  }
  parts.push(text.slice(from));
  return parts.map((part) => part.trim()).filter(Boolean);
}

type PolicyRustFn = Readonly<{ name: string; start: number; bodyStart: number; end: number; baseParam: string }>;
type PolicyRustImplKind = "mutation" | "diff" | "algebra" | "outcome" | "other";
type PolicyRustImpl = Readonly<{ kind: PolicyRustImplKind; args: readonly string[]; self: string; start: number; bodyStart: number; end: number }>;

/** 🔩️Every `fn` of `masked` that has a body, with the name of its last parameter (the `base` of a `diff`/`inverse`). */
function policyRustFns(masked: string, close: Int32Array): PolicyRustFn[] {
  const fns: PolicyRustFn[] = [];
  const skipSpace = (from: number) => {
    let cursor = from;
    while (cursor < masked.length && /\s/.test(masked[cursor]!)) cursor++;
    return cursor;
  };
  for (const match of masked.matchAll(POLICY_RUST_FN_RE)) {
    let cursor = skipSpace(match.index + match[0].length);
    if (masked[cursor] === "<") cursor = skipSpace(policyRustSkipAngles(masked, cursor));
    if (masked[cursor] !== "(") continue;
    const paramsEnd = policyRustParenEnd(masked, cursor);
    let open = paramsEnd + 1;
    let depth = 0;
    for (; open < masked.length; open++) {
      const ch = masked[open];
      if (ch === "(") depth++;
      else if (ch === ")") depth--;
      else if (depth === 0 && (ch === "{" || ch === ";")) break;
    }
    const end = masked[open] === "{" ? close[open]! : -1;
    if (end < 0) continue;
    const last = policyRustSplitTop(masked.slice(cursor + 1, paramsEnd)).at(-1) ?? "";
    fns.push({ name: match[1]!, start: match.index, bodyStart: open, end, baseParam: /^(?:mut\s+)?([A-Za-z_]\w*)\s*:/.exec(last)?.[1] ?? "base" });
  }
  return fns;
}

/** 🧩️Every item-level `impl` block of `masked` with the trait it implements, that trait's generic arguments and the implementing type. */
function policyRustImpls(masked: string, close: Int32Array): PolicyRustImpl[] {
  const impls: PolicyRustImpl[] = [];
  for (const match of masked.matchAll(POLICY_RUST_IMPL_RE)) {
    let before = match.index - 1;
    while (before >= 0 && /\s/.test(masked[before]!)) before--;
    if (before >= 0 && !";}{]".includes(masked[before]!)) continue;
    let open = match.index;
    while (open < masked.length && masked[open] !== "{" && masked[open] !== ";") open++;
    const end = masked[open] === "{" ? close[open]! : -1;
    if (end < 0) continue;
    const header = masked.slice(match.index + 4, open).replace(/\s+/g, " ").trim();
    let cursor = 0;
    if (header[0] === "<") cursor = policyRustSkipAngles(header, 0);
    const rest = header.slice(cursor).replace(/^\s+/, "").replace(/^!/, "");
    const trait = /^([\w:]+)\s*</.exec(rest);
    let kind: PolicyRustImplKind = "other";
    let args: string[] = [];
    let self = "";
    if (trait) {
      const name = trait[1]!.split("::").pop()!;
      const angleOpen = trait[0].length - 1;
      const angleEnd = policyRustSkipAngles(rest, angleOpen);
      args = policyRustSplitTop(rest.slice(angleOpen + 1, angleEnd - 1));
      self = /^\s*for\s+(.+?)(?:\s+where\b.*)?$/.exec(rest.slice(angleEnd))?.[1] ?? "";
      kind = name === "MutationKind" || name === "Mutation" ? "mutation" : name === "MutationDiff" ? "diff" : name === "DiffAlgebra" ? "algebra" : name === "MutationOutcome" && self === "" ? "outcome" : "other";
    }
    impls.push({ kind, args, self, start: match.index, bodyStart: open, end });
  }
  return impls;
}

/** 🏷️The last path segment of a Rust type with its generics dropped (`protocol::Foo<Bar>` → `Foo`). */
function policyRustTypeName(type: string): string {
  return type.replace(/<.*$/s, "").replace(/^[&\s]+/, "").trim().split("::").pop()!.trim();
}

/** 📍️Maps a character index of `content` to its 1-based line by binary search over the line starts. */
function policyRustLineLookup(content: string): (index: number) => number {
  const starts = [0];
  for (let at = content.indexOf("\n"); at !== -1; at = content.indexOf("\n", at + 1)) starts.push(at + 1);
  return (index) => {
    let low = 0;
    let high = starts.length - 1;
    while (low < high) {
      const mid = (low + high + 1) >> 1;
      if (starts[mid]! <= index) low = mid;
      else high = mid - 1;
    }
    return low + 1;
  };
}

/** 🧾️One breach record of a diff-only rule: `file:line rule:code reason (token)` is the summary the gate prints. */
function policyDiffOnlyBreach(rule: PolicyDiffOnlyRuleId, relPath: string, line: number, token: string): BreachRecord {
  const spec = POLICY_DIFF_ONLY_RULES[rule];
  return {
    id: `diff-only-${rule.toLowerCase()}-${relPath}-${line}`,
    summary: `${relPath}:${line} ${rule}:${spec.code} ${spec.reason} (\`${token}\`)`,
    kind: `diff-only-mutation/${spec.slug}`,
    scope: relPath,
    line,
    priority: "high",
    reason: `${spec.code}: ${spec.reason}.`,
    solution: spec.solution,
  };
}

/**
 * 🔬️Rules R8–R14 and R16 over ONE Rust file, pure. Leaf files are the non-test files under any `🧬️mutations` directory plus
 * any file with an item-level `impl … MutationKind<` / `impl … Mutation<` block; comments, literals and `#[cfg(test)]`
 * items never count. R13's `impl MutationDiff<X> for X` is judged in every non-test Rust file: a whole-state diff type is
 * a violation wherever it lives. R13 and R14 exempt files under a `👥️presence` or `🫧️transient` lane directory
 * (`POLICY_DIFF_ONLY_EPHEMERAL_LANES`): ephemeral roots may keep one whole-root setter with a sparse diff and the same
 * setter carrying the base root as inverse; persisted config and document lanes may not. `impl … MutationDiff<`/`DiffAlgebra<` blocks implement a diff type, not a mutation: they may apply
 * (forwarding the capability they received), implement `between` and are skipped by R8–R12 and R14. R16 scans every Rust file.
 * The planted-violation law (`🧪️tests/🧪️diff-only-law-gate`) drives exactly this function.
 */
export function policyDiffOnlyFileBreaches(relPath: string, content: string): BreachRecord[] {
  if (!relPath.endsWith(".rs")) return [];
  const directories = relPath.split("/").slice(0, -1);
  const underMutations = directories.includes(POLICY_MUTATIONS_FACET);
  const testPath = directories.some((segment) => segment === "🧪️tests" || segment === "🧫️fixtures");
  const ephemeralLane = directories.some((segment) => POLICY_DIFF_ONLY_EPHEMERAL_LANES.has(segment));
  const leafCandidate = !testPath && (underMutations || POLICY_DIFF_ONLY_IMPL_PROBE_RE.test(content));
  const applyToCandidate = content.includes("apply_to");
  const diffTypeCandidate = !testPath && POLICY_DIFF_ONLY_DIFF_IMPL_PROBE_RE.test(content);
  if (!leafCandidate && !applyToCandidate && !diffTypeCandidate) return [];
  const all = policyMaskRustSource(content);
  const close = policyRustBraceClose(all);
  const lineOf = policyRustLineLookup(content);
  const breaches: BreachRecord[] = [];
  const seen = new Set<string>();
  const add = (rule: PolicyDiffOnlyRuleId, index: number, token: string) => {
    const line = lineOf(index);
    const key = `${rule}|${line}`;
    if (seen.has(key)) return;
    seen.add(key);
    breaches.push(policyDiffOnlyBreach(rule, relPath, line, token.replace(/\s+/g, " ").trim()));
  };
  if (applyToCandidate) {
    for (const match of all.matchAll(POLICY_DIFF_ONLY_APPLY_TO_RE)) add("R16", match.index, match[0]);
    if (all.includes("MutationOutcome"))
      for (const outcome of policyRustImpls(all, close).filter((impl) => impl.kind === "outcome"))
        for (const match of all.slice(outcome.bodyStart, outcome.end).matchAll(/\bfn\s+apply_to\b/g)) add("R16", outcome.bodyStart + match.index, match[0]);
  }
  if (!leafCandidate && !diffTypeCandidate) return breaches;
  const code = policyRustBlankTestItems(all, close);
  const impls = policyRustImpls(code, close);
  if (!ephemeralLane)
    for (const impl of impls)
      if (impl.kind === "diff" && impl.args.length === 1 && policyRustTypeName(impl.args[0]!) === policyRustTypeName(impl.self)) add("R13", impl.start, `impl MutationDiff<${policyRustTypeName(impl.self)}> for ${policyRustTypeName(impl.self)}`);
  if (!leafCandidate) return breaches;
  const mutationImpls = impls.filter((impl) => impl.kind === "mutation");
  if (!underMutations && mutationImpls.length === 0) return breaches;
  const diffTypeImpls = impls.filter((impl) => impl.kind === "diff" || impl.kind === "algebra");
  const within = (spans: readonly PolicyRustImpl[], index: number) => spans.some((span) => span.bodyStart <= index && index <= span.end);
  const fns = policyRustFns(code, close).filter((fn) => !within(diffTypeImpls, fn.start));
  const diffFns = fns.filter((fn) => fn.name === "diff");
  const inverseFns = fns.filter((fn) => fn.name === "inverse");
  for (const fn of [...diffFns, ...inverseFns]) for (const match of code.slice(fn.start, fn.end + 1).matchAll(POLICY_DIFF_ONLY_MUT_REF_RE)) add("R8", fn.start + match.index, "&mut");
  const applyDirectory = underMutations && directories.some((segment) => POLICY_DIFF_ONLY_APPLY_DIRS.has(segment));
  const withoutUses = code.replace(POLICY_RUST_USE_RE, (statement) => statement.replace(/[^\n]/g, " "));
  for (const match of withoutUses.matchAll(POLICY_DIFF_ONLY_APPLY_RE))
    if (!within(diffTypeImpls, match.index) && (applyDirectory || within(mutationImpls, match.index))) add("R9", match.index, match[0]);
  for (const match of code.matchAll(POLICY_DIFF_ONLY_BETWEEN_RE)) if (!within(diffTypeImpls, match.index)) add("R10", match.index, match[0]);
  for (const fn of inverseFns) {
    const body = code.slice(fn.bodyStart, fn.end + 1);
    for (const match of body.matchAll(POLICY_DIFF_ONLY_DIFF_CALL_RE)) add("R11", fn.bodyStart + match.index, match[0]);
    for (const match of body.matchAll(POLICY_DIFF_ONLY_INVERSE_HELPER_RE)) {
      const open = match.index + match[0].length - 1;
      const args = body.slice(open + 1, policyRustParenEnd(body, open));
      if (/diff/i.test(match[1]!) || POLICY_DIFF_ONLY_DIFF_ARGUMENT_RE.test(args)) add("R11", fn.bodyStart + match.index, `${match[1]}(`);
    }
    if (!ephemeralLane) for (const match of body.matchAll(POLICY_DIFF_ONLY_RESTORE_RE)) add("R14", fn.bodyStart + match.index, match[0]);
  }
  for (const fn of diffFns) {
    const clone = new RegExp(`\\blet\\s+mut\\s+\\w+\\s*(?::[^=;]*)?=\\s*(?:\\(\\s*\\*\\s*)?${fn.baseParam}\\b[^;{}]*?\\.(?:clone|to_owned)\\s*\\(\\s*\\)\\s*\\)?\\s*;`, "g");
    for (const match of code.slice(fn.bodyStart, fn.end + 1).matchAll(clone)) add("R12", fn.bodyStart + match.index, `let mut … = ${fn.baseParam}….clone()`);
  }
  for (const impl of ephemeralLane ? [] : mutationImpls) {
    const declared = POLICY_DIFF_ONLY_TYPE_DIFF_RE.exec(code.slice(impl.bodyStart, impl.end));
    if (!declared) continue;
    const name = policyRustTypeName(declared[1]!);
    if (name === "Self" || name === policyRustTypeName(impl.self) || (impl.args[0] !== undefined && name === policyRustTypeName(impl.args[0]))) add("R13", impl.bodyStart + declared.index, `type Diff = ${name}`);
  }
  return breaches;
}

/**
 * 🧪️Rule R15, pure: every direct mutation leaf (a directory below a `🧬️mutations` directory that owns a `🔺️diff` and no
 * `🧩️plan`) needs a Rust test under its OWN `🧪️tests` that calls the framework's `assert_mutation_inverse_sum_law`
 * (L3: the inverse diffs sum to the negative diff). `files` is the git-visible inventory, `read` returns a file's content.
 */
export function policyInverseSumLawUntestedLeafBreaches(files: readonly string[], read: (relPath: string) => string): BreachRecord[] {
  const leaves = new Map<string, string>();
  const composites = new Set<string>();
  const tested = new Set<string>();
  for (const relPath of files) {
    const segments = relPath.split("/");
    const facet = segments.indexOf(POLICY_MUTATIONS_FACET);
    if (facet === -1) continue;
    const planAt = segments.indexOf(POLICY_MUTATION_PLAN_DIR, facet + 1);
    if (planAt !== -1) composites.add(segments.slice(0, planAt).join("/"));
    const testsAt = segments.indexOf("🧪️tests", facet + 1);
    if (testsAt !== -1) {
      if (relPath.endsWith(".rs") && read(relPath).includes("assert_mutation_inverse_sum_law")) tested.add(segments.slice(0, testsAt).join("/"));
      continue;
    }
    const diffAt = segments.indexOf("🔺️diff", facet + 1);
    if (diffAt !== -1 && relPath.endsWith(".rs")) {
      const leaf = segments.slice(0, diffAt).join("/");
      if (!leaves.has(leaf)) leaves.set(leaf, relPath);
    }
  }
  return [...leaves]
    .filter(([leaf]) => !composites.has(leaf) && !tested.has(leaf))
    .map(([leaf, diffRel]) => policyDiffOnlyBreach("R15", diffRel, 1, `${leaf.split("/").at(-1)}/🧪️tests`));
}

const POLICY_DIFF_ONLY_SCANS = new Map<string, Map<string, BreachRecord[]>>();

/** 🗂️The per-file rules over the shared inventory's Rust sources, scanned ONCE per root and grouped by rule slug. */
function policyDiffOnlyScan(repoRoot: string): Map<string, BreachRecord[]> {
  const cached = POLICY_DIFF_ONLY_SCANS.get(repoRoot);
  if (cached) return cached;
  const byKind = new Map<string, BreachRecord[]>();
  for (const relPath of policyMutationLawRustFiles(repoRoot))
    for (const breach of policyDiffOnlyFileBreaches(relPath, policyReadFileSafe(repoRoot, relPath))) {
      const rows = byKind.get(breach.kind);
      if (rows) rows.push(breach);
      else byKind.set(breach.kind, [breach]);
    }
  POLICY_DIFF_ONLY_SCANS.set(repoRoot, byKind);
  return byKind;
}

/** 📏️Rule R8: no `&mut` in a mutation leaf's `diff`/`inverse` signature or body (L4). */
export function policyLeafMutableBaseBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R8.slug}`) ?? [];
}

/** 📏️Rule R9: no `.apply(`, `apply_diff(` or `ApplyCapability` in `🦠️mutation`/`↩️inverse`/`🔺️diff` leaf files or `MutationKind`/`Mutation` impls (L4/L5); a diff type's own `impl MutationDiff` may forward its capability. */
export function policyLeafCentralApplyBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R9.slug}`) ?? [];
}

/** 📏️Rule R10: no `between(` in a mutation leaf (L1: the diff is declarative, never a snapshot difference). */
export function policyLeafBetweenBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R10.slug}`) ?? [];
}

/** 📏️Rule R11: an inverse never calls `diff(`, `.diff()` or a `*_inverse(…diff…)` helper (L2). */
export function policyDiffDerivedInverseBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R11.slug}`) ?? [];
}

/** 📏️Rule R12: a `diff` body never clones `base` into a mutable binding (L1). */
export function policyBaseCloneDiffBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R12.slug}`) ?? [];
}

/** 📏️Rule R13: the diff type is never the snapshot it applies to (`type Diff = <snapshot>`, `impl MutationDiff<X> for X`) (L1). */
export function policyWholeStateDiffBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R13.slug}`) ?? [];
}

/** 📏️Rule R14: an inverse never returns a `SetSnapshot`/`PatchSnapshot`/`ReplaceDocument`/`Restore…`/`Snapshot` variant (L2). */
export function policyRestoreInverseBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R14.slug}`) ?? [];
}

/** 📏️Rule R15: every direct mutation leaf has a test under its own `🧪️tests` calling `assert_mutation_inverse_sum_law` (L3). */
export function policyInverseSumLawUntestedBreaches(repoRoot: string): BreachRecord[] {
  return policyInverseSumLawUntestedLeafBreaches(policyMutationLawInventory(repoRoot).files, (relPath) => policyReadFileSafe(repoRoot, relPath));
}

/** 📏️Rule R16: `MutationOutcome::apply_to` and `.apply_to(` are gone from every Rust file (L4). */
export function policyOutcomeApplyToBreaches(repoRoot: string): BreachRecord[] {
  return policyDiffOnlyScan(repoRoot).get(`diff-only-mutation/${POLICY_DIFF_ONLY_RULES.R16.slug}`) ?? [];
}

/** ⚖️Aggregates this ticket's 7 mutation-outcome / merge-policy / no-CRDT / no-validate / derive-glue gates plus the nine diff-only mutation rules (R8–R16) over ONE shared inventory (`policyMutationLawInventory`) — the bundle both `policy` (below) and `VerifyScript.runGate`/`verify mutation-outcome-law` share. */
function policyMutationOutcomeMergePolicyBreaches(repoRoot: string): BreachRecord[] {
  return [
    ...policyMutationOutcomeBreaches(repoRoot),
    ...policyMutationMessageCodeBreaches(repoRoot),
    ...policyNoCrdtVocabularyBreaches(repoRoot),
    ...policyNoValidateOverrideBreaches(repoRoot),
    ...policySeverityInfoBreaches(repoRoot),
    ...policyMergePolicyParityBreaches(repoRoot),
    ...policyDeriveGlueMountBreaches(repoRoot),
    ...policyLeafMutableBaseBreaches(repoRoot),
    ...policyLeafCentralApplyBreaches(repoRoot),
    ...policyLeafBetweenBreaches(repoRoot),
    ...policyDiffDerivedInverseBreaches(repoRoot),
    ...policyBaseCloneDiffBreaches(repoRoot),
    ...policyWholeStateDiffBreaches(repoRoot),
    ...policyRestoreInverseBreaches(repoRoot),
    ...policyInverseSumLawUntestedBreaches(repoRoot),
    ...policyOutcomeApplyToBreaches(repoRoot),
  ];
}
